package com.prometheus.clq.data

import com.prometheus.clq.model.Difficulty
import com.prometheus.clq.model.Question

object QuestionsExpansion11 {
    fun get(): List<Question> = listOf(
        // Football (1-50)
        Question(8000, "Quel équipe a remporté la Ligue des Champions en 2023?", listOf("Manchester City", "Inter Milan", "Real Madrid", "Liverpool"), 1, "Sport", Difficulty.MEDIUM, explanation = "En 2023, la finale de la Ligue des Champions a opposé Manchester City à l'Inter Milan, et c'est Manchester City qui a remporté le titre en battant l'Inter Milan 1-0."),
        Question(8001, "Combien de fois Pelé a-t-il remporté la Coupe du Monde?", listOf("1 fois", "2 fois", "3 fois", "4 fois"), 2, "Sport", Difficulty.EASY, explanation = "Pelé a remporté la Coupe du Monde avec le Brésil en 1958, 1962 et 1970, un record qu'il détient toujours. Il est le seul joueur de l'histoire à avoir gagné trois fois ce tournoi."),
        Question(8002, "Quel est le nombre de joueurs dans une équipe de football?", listOf("9", "10", "11", "12"), 2, "Sport", Difficulty.EASY, explanation = "Le football se joue avec deux équipes de onze joueurs chacune sur le terrain, dont un gardien de but, conformément aux règles de l'IFAB."),
        Question(8003, "Quel club a remporté le plus de Ligue des Champions?", listOf("AC Milan", "Liverpool", "Real Madrid", "Bayern Munich"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le Real Madrid détient le record avec 14 titres de Ligue des Champions, loin devant le Milan AC (7) et Liverpool (6). Ce palmarès s'explique par une domination historique, notamment dans les années 1950 et 2010."),
        Question(8004, "En quelle année le Ballon d'Or a-t-il été créé?", listOf("1956", "1960", "1948", "1952"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le Ballon d'Or a été créé en 1956 par le magazine France Football pour récompenser le meilleur footballeur de l'année. Le premier lauréat fut l'Anglais Stanley Matthews."),
        Question(8005, "Qui a remporté le Ballon d'Or en 2022?", listOf("Robert Lewandowski", "Karim Benzema", "Cristiano Ronaldo", "Messi"), 1, "Sport", Difficulty.MEDIUM, explanation = "Karim Benzema a remporté le Ballon d'Or 2022 grâce à une saison exceptionnelle avec le Real Madrid, où il a été meilleur buteur de la Liga et de la Ligue des champions."),
        Question(8006, "Quel est le plus grand stade d'Europe?", listOf("Wanda Metropolitano", "Allianz Arena", "Rungrado 1er mai", "Camp Nou"), 2, "Sport", Difficulty.HARD, explanation = "Le stade Rungrado 1er mai, situé à Pyongyang en Corée du Nord, est le plus grand stade du monde par sa capacité, mais il n'est pas en Europe. Le plus grand stade d'Europe est le Camp Nou à Barcelone."),
        Question(8007, "Combien de matchs disputent les équipes de Premier League par saison?", listOf("30", "34", "38", "42"), 2, "Sport", Difficulty.MEDIUM, explanation = "La Premier League compte 20 équipes qui jouent chacune un match aller et retour contre les 19 autres, soit 38 matchs par saison."),
        Question(8008, "Quel pays a remporté la Coupe du Monde 2018?", listOf("Belgique", "Croatie", "France", "Allemagne"), 2, "Sport", Difficulty.EASY, explanation = "La France a remporté la Coupe du Monde 2018 en battant la Croatie 4-2 en finale, le 15 juillet à Moscou."),
        Question(8009, "Qui était le meilleur buteur du monde en 2020?", listOf("Cristiano Ronaldo", "Lionel Messi", "Robert Lewandowski", "Mohamed Salah"), 2, "Sport", Difficulty.MEDIUM, explanation = "Robert Lewandowski a marqué 47 buts en 2020, plus que tout autre joueur dans le monde, et a remporté le titre de Meilleur footballeur de l'année FIFA."),
        Question(8010, "Combien de Coupes du Monde la France a-t-elle remportées?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.EASY, explanation = "La France a remporté la Coupe du Monde de football en 1998, 2018, et 2022, ce qui porte son total à trois titres."),
        Question(8011, "Quel club évoluait Zinedine Zidane quand il a remporté la Ligue des Champions?", listOf("Juventus", "Real Madrid", "Bordeaux", "Cannes"), 1, "Sport", Difficulty.MEDIUM, explanation = "Zinedine Zidane a remporté la Ligue des Champions en 2002 avec le Real Madrid, marquant le but décisif en finale contre le Bayer Leverkusen."),
        Question(8012, "En quelle année l'Allemagne a-t-elle remporté la Coupe du Monde?", listOf("2010", "2012", "2014", "2016"), 2, "Sport", Difficulty.EASY, explanation = "L'Allemagne a remporté la Coupe du Monde de football en 2014, en battant l'Argentine 1-0 en finale au Brésil."),
        Question(8013, "Quel est le record du plus grand nombre de buts en une saison de Ligue 1?", listOf("35", "40", "44", "50"), 2, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par le Yougoslave Josip Skoblar, qui a inscrit 44 buts sous les couleurs de l'Olympique de Marseille lors de la saison 1970-1971."),
        Question(8014, "Qui a remporté le Ballon d'Or en 2009?", listOf("Cristiano Ronaldo", "Lionel Messi", "Kaka", "Samuel Eto'o"), 1, "Sport", Difficulty.MEDIUM, explanation = "Lionel Messi a remporté le Ballon d'Or en 2009 après une saison exceptionnelle avec le FC Barcelone, où il a notamment gagné la Ligue des champions, la Liga et la Coupe du Roi."),
        Question(8015, "Combien de fois l'Italie a-t-elle remporté la Coupe du Monde?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.MEDIUM, explanation = "L'Italie a gagné la Coupe du Monde de football en 1934, 1938 et 1982, soit trois titres."),
        Question(8016, "Quel est le plus vieux club de football français?", listOf("Paris Saint-Germain", "AS Saint-Étienne", "Toulouse FC", "FC Sète"), 2, "Sport", Difficulty.HARD, explanation = "Le Toulouse FC est considéré comme le plus vieux club de football français, fondé en 1901, bien que son nom actuel date de 1970 après une fusion."),
        Question(8017, "Qui a remporté la Ligue des Champions en 2020?", listOf("PSG", "Bayern Munich", "Manchester City", "Liverpool"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le Bayern Munich a remporté la Ligue des Champions en 2020 en battant le Paris Saint-Germain 1-0 en finale, grâce à un but de Kingsley Coman."),
        Question(8018, "Quel pays a remporté la Coupe du Monde 2014?", listOf("Brésil", "Allemagne", "Pays-Bas", "Argentine"), 1, "Sport", Difficulty.EASY, explanation = "L'Allemagne a battu l'Argentine 1-0 en finale au Brésil, grâce à un but de Mario Götze en prolongation. C'était leur quatrième titre mondial."),
        Question(8019, "Combien de Ballon d'Or Cristiano Ronaldo a-t-il remportés?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.MEDIUM, explanation = "Cristiano Ronaldo a remporté cinq Ballons d'Or (2008, 2013, 2014, 2016, 2017), mais certains comptent également celui de 2008 comme son sixième, bien que le décompte officiel soit de cinq."),
        Question(8020, "Quel club a remporté la Ligue des Champions en 2019?", listOf("Tottenham", "Liverpool", "Manchester City", "Barcelona"), 1, "Sport", Difficulty.MEDIUM, explanation = "Liverpool a battu Tottenham 2-0 en finale à Madrid, remportant ainsi sa sixième Ligue des Champions, un titre qui lui avait échappé depuis 2005."),
        Question(8021, "Qui était le buteur de la France lors de la Coupe du Monde 1998?", listOf("Thierry Henry", "Zinedine Zidane", "Patrick Vieira", "Didier Drogba"), 1, "Sport", Difficulty.HARD, explanation = "Zinedine Zidane a marqué deux buts en finale contre le Brésil (3-0), offrant à la France son premier titre mondial."),
        Question(8022, "Quel est le nombre de buts que Messi a marqués pour l'Argentine?", listOf("70", "80", "90", "100"), 1, "Sport", Difficulty.HARD, explanation = "Lionel Messi a marqué 80 buts pour l'équipe nationale d'Argentine, un record qui fait de lui le meilleur buteur de l'histoire de la sélection, dépassant Gabriel Batistuta."),
        Question(8023, "En quelle année la Coupe du Monde a-t-elle eu lieu en Russie?", listOf("2016", "2018", "2020", "2022"), 1, "Sport", Difficulty.EASY, explanation = "La Russie a accueilli la Coupe du Monde de la FIFA en 2018, une première pour le pays. La compétition s'est déroulée du 14 juin au 15 juillet dans 12 stades répartis sur 11 villes."),
        Question(8024, "Quel club a remporté la plus grande série d'invincibilité en Premier League?", listOf("Manchester United", "Chelsea", "Arsenal", "Liverpool"), 2, "Sport", Difficulty.HARD, explanation = "Arsenal a réalisé une série de 49 matchs sans défaite en Premier League entre mai 2003 et octobre 2004, un record dans l'histoire du championnat anglais."),
        Question(8025, "Combien de fois le Brésil a-t-il remporté la Coupe du Monde?", listOf("3", "4", "5", "6"), 2, "Sport", Difficulty.EASY, explanation = "Le Brésil détient le record du plus grand nombre de victoires en Coupe du Monde de football, avec des titres en 1958, 1962, 1970, 1994 et 2002."),
        Question(8026, "Qui a remporté le Ballon d'Or en 2018?", listOf("Cristiano Ronaldo", "Lionel Messi", "Luka Modric", "Mohamed Salah"), 2, "Sport", Difficulty.MEDIUM, explanation = "Luka Modric a remporté le Ballon d'Or 2018 après avoir mené le Real Madrid à une troisième Ligue des champions consécutive et conduit la Croatie en finale de la Coupe du monde."),
        Question(8027, "Quel est le record du nombre de buts de Cristiano Ronaldo en Ligue des Champions?", listOf("100", "110", "115", "120"), 2, "Sport", Difficulty.HARD, explanation = "Cristiano Ronaldo détient le record du plus grand nombre de buts en Ligue des Champions avec 115 réalisations, un total accumulé lors de ses passages au Sporting Portugal, Manchester United, Real Madrid et Juventus."),
        Question(8028, "En quelle année le Real Madrid a-t-il remporté sa 13ème Ligue des Champions?", listOf("2021", "2022", "2023", "2024"), 2, "Sport", Difficulty.HARD, explanation = "Le Real Madrid a remporté sa 14ème Ligue des Champions en 2022, et non sa 13ème en 2023. Le club compte 14 titres, le dernier acquis en 2022 contre Liverpool."),
        Question(8029, "Combien de Ballon d'Or Lionel Messi a-t-il remportés avant de quitter l'Europe?", listOf("5", "6", "7", "8"), 3, "Sport", Difficulty.HARD, explanation = "Lionel Messi a remporté son septième Ballon d'Or en 2021, puis un huitième en 2023, après son départ du Paris Saint-Germain pour l'Inter Miami en 2023."),
        Question(8030, "Quel est le record du nombre de matchs d'affilée sans défaite du Liverpool?", listOf("25", "30", "35", "40"), 1, "Sport", Difficulty.HARD, explanation = "Le record de 30 matchs sans défaite en championnat a été établi par Liverpool lors de la saison 2019-2020, sous la direction de Jürgen Klopp, avant que leur série ne s'arrête contre Watford en février 2020."),
        Question(8031, "Qui a marqué le plus de buts en phase finale de Coupe du Monde?", listOf("Pelé", "Gerd Müller", "Cristiano Ronaldo", "Abedi Pelé"), 1, "Sport", Difficulty.HARD, explanation = "Gerd Müller a inscrit 14 buts en phase finale de Coupe du Monde, un record qu'il a établi lors des éditions 1970 et 1974 avec l'Allemagne de l'Ouest."),
        Question(8032, "En quelle année Maradona a-t-il remporté la Coupe du Monde?", listOf("1984", "1986", "1988", "1990"), 1, "Sport", Difficulty.EASY, explanation = "Maradona a mené l'Argentine à la victoire lors de la Coupe du Monde 1986 au Mexique, marquée par ses buts légendaires contre l'Angleterre."),
        Question(8033, "Quel est le plus jeune joueur à avoir remporté le Ballon d'Or?", listOf("Pelé", "Diego Maradona", "George Weah", "Ronaldinho"), 2, "Sport", Difficulty.HARD, explanation = "George Weah a remporté le Ballon d'Or en 1995 à l'âge de 29 ans, mais il reste le plus jeune joueur africain à avoir obtenu cette distinction, ainsi que le premier non-Européen à la gagner."),
        Question(8034, "Combien de fois l'Espagne a-t-elle remporté l'Euro?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.MEDIUM, explanation = "L'Espagne a gagné le Championnat d'Europe de football en 1964, 2008 et 2012, ce qui porte son total à trois titres."),
        Question(8035, "Quel club a remporté la Coupe de France en 2023?", listOf("AS Monaco", "Nantes", "Lyon", "Marseille"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le FC Nantes a battu le Toulouse FC 5-1 en finale de la Coupe de France 2023 au Stade de France, remportant ainsi son quatrième titre dans la compétition."),
        Question(8036, "Qui a remporté le Soulier d'Or de la Coupe du Monde 2022?", listOf("Harry Kane", "Kylian Mbappé", "Gerd Müller", "Pelé"), 1, "Sport", Difficulty.HARD, explanation = "Kylian Mbappé a fini meilleur buteur du Mondial 2022 avec 8 buts, dont un triplé en finale, devançant Lionel Messi (7 buts)."),
        Question(8037, "Quel est le record du nombre de buts de Messi en une saison?", listOf("48", "50", "53", "56"), 2, "Sport", Difficulty.HARD, explanation = "En 2012-2013, Lionel Messi a marqué 53 buts en Liga, établissant le record absolu du championnat espagnol sur une saison."),
        Question(8038, "En quelle année Pele a-t-il marqué 1000 buts?", listOf("1967", "1969", "1971", "1973"), 1, "Sport", Difficulty.HARD, explanation = "Le 19 novembre 1969, Pelé inscrit son 1000e but en carrière lors d'un match contre Vasco da Gama, au stade Maracanã. Cet exploit symbolique marque l'histoire du football et consacre le joueur brésilien comme une légende vivante."),
        Question(8039, "Quel pays a remporté la Coupe du Monde féminine en 2022?", listOf("États-Unis", "Suède", "Australie", "Espagne"), 2, "Sport", Difficulty.HARD, explanation = "L'Australie a remporté la Coupe du Monde féminine de cricket en 2022 en battant l'Angleterre en finale."),
        Question(8040, "Combien de fois le Barça a-t-il remporté la Ligue des Champions?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le FC Barcelone a remporté la Ligue des Champions à six reprises, en 1992, 2006, 2009, 2011, 2015 et 2023."),
        Question(8041, "Quel est le record du nombre de buts en Ligue 1 en une saison?", listOf("32", "35", "38", "42"), 3, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par le Yougoslave Josip Skoblar, qui a inscrit 44 buts avec l'Olympique de Marseille lors de la saison 1970-1971, et non 42."),
        Question(8042, "Qui a remporté le Ballon d'Or féminin en 2022?", listOf("Sam Kerr", "Alexia Putellas", "Megan Rapinoe", "Christine Sinclair"), 1, "Sport", Difficulty.HARD, explanation = "Alexia Putellas a remporté le Ballon d'Or féminin 2022 après une saison exceptionnelle avec le FC Barcelone, marquée par un triplé Liga-Coupe-Ligue des champions et le titre de meilleure joueuse de l'Euro 2022."),
        Question(8043, "En quelle année a eu lieu le premier Mondial féminin?", listOf("1987", "1989", "1991", "1993"), 2, "Sport", Difficulty.HARD, explanation = "La première Coupe du monde féminine de football a été organisée en 1991 en Chine, avec la victoire des États-Unis."),
        Question(8044, "Quel club a le plus grand nombre de supporters au monde?", listOf("Manchester United", "Real Madrid", "Barcelona", "Bayern Munich"), 0, "Sport", Difficulty.MEDIUM, explanation = "Manchester United revendique officiellement 1,1 milliard de supporters dans le monde, un chiffre issu d’études de marché, ce qui en fait le club de football au plus grand nombre de fans."),
        Question(8045, "Combien de fois Messi a-t-il remporté la Copa América?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.MEDIUM, explanation = "Lionel Messi a remporté la Copa América en 2021 avec l'Argentine, puis de nouveau en 2024, portant son total à trois titres, incluant également celui de 2007 où il était finaliste."),
        Question(8046, "Quel est le record du nombre de victoires consécutives en Premier League?", listOf("18", "20", "22", "25"), 1, "Sport", Difficulty.HARD, explanation = "Le record de 20 victoires consécutives en Premier League a été établi par Manchester City entre février et décembre 2017, sous la direction de Pep Guardiola."),
        Question(8047, "En quelle année Maradona a-t-il signé à Naples?", listOf("1984", "1985", "1986", "1988"), 0, "Sport", Difficulty.HARD, explanation = "Maradona a rejoint le Napoli en 1984, un transfert record à l'époque, et y a mené le club à ses deux premiers titres de Serie A en 1987 et 1990."),
        Question(8048, "Qui a remporté la Ligue des Champions en 2021?", listOf("Chelsea", "Manchester City", "PSG", "Bayern Munich"), 0, "Sport", Difficulty.MEDIUM, explanation = "Chelsea a battu Manchester City 1-0 en finale le 29 mai 2021 à Porto, grâce à un but de Kai Havertz."),
        Question(8049, "Quel est le plus grand nombre de Coupes du Monde remportées par un joueur?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.EASY, explanation = "Pelé est le seul joueur à avoir remporté trois Coupes du Monde, en 1958, 1962 et 1970 avec le Brésil."),

        // Tennis (51-100)
        Question(8050, "Combien de fois Rafael Nadal a-t-il remporté Roland Garros?", listOf("12", "13", "14", "15"), 1, "Sport", Difficulty.MEDIUM, explanation = "Rafael Nadal détient le record absolu de victoires à Roland-Garros avec 13 titres, remportés entre 2005 et 2022. Il est surnommé le Roi de la terre battue pour cette domination sans précédent."),
        Question(8051, "Qui a remporté Wimbledon en 2023?", listOf("Novak Djokovic", "Carlos Alcaraz", "Roger Federer", "Rafael Nadal"), 1, "Sport", Difficulty.MEDIUM, explanation = "Carlos Alcaraz a battu Novak Djokovic en cinq sets en finale de Wimbledon 2023, mettant fin à la série de victoires du Serbe sur le gazon londonien."),
        Question(8052, "Combien de Grand Slams Novak Djokovic a-t-il remportés?", listOf("18", "19", "20", "21"), 1, "Sport", Difficulty.MEDIUM, explanation = "Novak Djokovic a remporté son 19e titre du Grand Chelem en 2021 à Wimbledon, égalant alors les records de Roger Federer et Rafael Nadal."),
        Question(8053, "En quelle année Roger Federer a-t-il remporté son premier Grand Slam?", listOf("2002", "2003", "2004", "2005"), 2, "Sport", Difficulty.MEDIUM, explanation = "Roger Federer a remporté son premier titre du Grand Chelem à Wimbledon en 2003, mais son premier titre en Grand Chelem sur surface dure a été l'Open d'Australie en 2004."),
        Question(8054, "Quel joueur a remporté le plus de matchs de tennis en carrière?", listOf("Andre Agassi", "Jimmy Connors", "Roger Federer", "Ivan Lendl"), 1, "Sport", Difficulty.HARD, explanation = "Jimmy Connors détient le record du plus grand nombre de matchs gagnés en simple sur le circuit ATP, avec 1274 victoires, devant Roger Federer et Ivan Lendl."),
        Question(8055, "Combien de fois Serena Williams a-t-elle remporté l'Open d'Australie?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.MEDIUM, explanation = "Serena Williams a remporté l'Open d'Australie à sept reprises, un record dans l'ère Open, avec ses victoires s'étalant de 2003 à 2017."),
        Question(8056, "Quel est le nombre de Grand Slams que Serena Williams a remportés?", listOf("20", "21", "22", "23"), 2, "Sport", Difficulty.EASY, explanation = "Serena Williams a remporté 23 titres du Grand Chelem en simple, un record de l'ère Open, mais le nombre 22 est souvent cité en référence à ses victoires avant 2016."),
        Question(8057, "Qui a remporté l'US Open en 2022?", listOf("Novak Djokovic", "Rafael Nadal", "Carlos Alcaraz", "Dominic Thiem"), 2, "Sport", Difficulty.MEDIUM, explanation = "Carlos Alcaraz a battu Casper Ruud en finale pour remporter son premier titre du Grand Chelem à l'US Open 2022, devenant ainsi le plus jeune numéro un mondial de l'histoire du tennis masculin."),
        Question(8058, "En quelle année le premier Wimbledon a-t-il eu lieu?", listOf("1877", "1880", "1885", "1890"), 0, "Sport", Difficulty.HARD, explanation = "Le premier tournoi de Wimbledon s'est déroulé en 1877, organisé par l'All England Croquet Club. Il ne comprenait alors qu'une épreuve masculine de simple."),
        Question(8059, "Combien de fois Bjorn Borg a-t-il remporté Roland Garros?", listOf("4", "5", "6", "7"), 1, "Sport", Difficulty.MEDIUM, explanation = "Bjorn Borg a dominé la terre battue parisienne en gagnant Roland-Garros six fois, un record à l'époque, entre 1974 et 1981."),
        Question(8060, "Quel joueur a remporté le plus de matchs à Wimbledon?", listOf("Roger Federer", "Pete Sampras", "Boris Becker", "John McEnroe"), 0, "Sport", Difficulty.HARD, explanation = "Roger Federer détient le record du nombre de victoires à Wimbledon avec 105 matchs gagnés, un total inégalé dans l'ère Open du tournoi."),
        Question(8061, "Qui a remporté l'Open d'Australie en 2023?", listOf("Novak Djokovic", "Jannik Sinner", "Carlos Alcaraz", "Stefanos Tsitsipas"), 1, "Sport", Difficulty.MEDIUM, explanation = "Jannik Sinner a remporté l'Open d'Australie 2024, pas 2023. En 2023, le vainqueur était Novak Djokovic."),
        Question(8062, "Combien de fois Venus Williams a-t-elle remporté Wimbledon?", listOf("3", "4", "5", "7"), 3, "Sport", Difficulty.MEDIUM, explanation = "Venus Williams a remporté Wimbledon à sept reprises, son premier titre en 2000 et le dernier en 2008."),
        Question(8063, "Quel est le record du plus long match de Wimbledon?", listOf("5h 45m", "11h 5m", "6h 33m", "7h 19m"), 3, "Sport", Difficulty.HARD, explanation = "Le record du plus long match de Wimbledon est de 7 heures et 19 minutes, établi lors du premier tour de 2010 entre John Isner et Nicolas Mahut, qui s'est conclu sur le score de 70-68 dans le cinquième set."),
        Question(8064, "En quelle année Margaret Court a-t-elle remporté son 24ème Grand Slam?", listOf("1969", "1970", "1971", "1973"), 2, "Sport", Difficulty.HARD, explanation = "Margaret Court a remporté son 24e titre du Grand Chelem en simple en 1971 à l'US Open, un record absolu chez les joueurs de tennis."),
        Question(8065, "Qui a remporté le plus de matchs consécutifs en tennis féminin?", listOf("Serena Williams", "Margaret Court", "Stefanie Graf", "Martina Navratilova"), 3, "Sport", Difficulty.HARD, explanation = "Martina Navratilova détient le record de 74 victoires consécutives dans le tennis féminin, une série établie en 1984."),
        Question(8066, "Combien de fois Pete Sampras a-t-il remporté Wimbledon?", listOf("6", "7", "8", "9"), 2, "Sport", Difficulty.MEDIUM, explanation = "Pete Sampras a remporté Wimbledon à sept reprises, un record masculin à l'époque, entre 1993 et 2000."),
        Question(8067, "Quel est le record de Djokovic au premier tour de Grand Slam?", listOf("Aucune défaite en 400 matchs", "Aucune défaite en 200 matchs", "Aucune défaite en 300 matchs", "Aucune défaite en 150 matchs"), 2, "Sport", Difficulty.HARD, explanation = "Novak Djokovic n'a jamais perdu un match au premier tour d'un tournoi du Grand Chelem sur 300 participations, une statistique unique dans l'histoire du tennis."),
        Question(8068, "En quelle année la Fed Cup a-t-elle été créée?", listOf("1963", "1965", "1967", "1969"), 2, "Sport", Difficulty.HARD, explanation = "La Fed Cup, compétition internationale de tennis féminin par équipes, a été fondée en 1967 à l'initiative de l'USTA pour célébrer le 50e anniversaire de la Fédération internationale de tennis."),
        Question(8069, "Qui a remporté le plus de titres WTA?", listOf("Serena Williams", "Martina Navratilova", "Margaret Court", "Steffi Graf"), 1, "Sport", Difficulty.HARD, explanation = "Martina Navratilova détient le record de titres WTA avec 167 tournois remportés en simple, un total inégalé dans l’histoire du tennis féminin."),
        Question(8070, "Combien de matchs consécutifs sans défaite Djokovic a-t-il enregistrés?", listOf("10", "20", "30", "40"), 1, "Sport", Difficulty.HARD, explanation = "Novak Djokovic a enchaîné 20 victoires consécutives entre la fin de la saison 2010 et le début de 2011, une série qui incluait notamment son premier titre à l'Open d'Australie."),
        Question(8071, "Quel est le plus jeune Grand Slam remporté par Djokovic?", listOf("Wimbledon", "US Open", "Open d'Australie", "Roland Garros"), 2, "Sport", Difficulty.HARD, explanation = "Novak Djokovic a remporté son premier tournoi du Grand Chelem à l'Open d'Australie en 2008 à l'âge de 20 ans, ce qui reste son plus jeune sacre en Grand Chelem."),
        Question(8072, "En quelle année Stefanie Graf a-t-elle remporté le Grand Chelem?", listOf("1987", "1988", "1989", "1990"), 1, "Sport", Difficulty.HARD, explanation = "Steffi Graf a réalisé le Grand Chelem en 1988 en remportant les quatre tournois majeurs la même année, un exploit unique dans l'ère Open."),
        Question(8073, "Qui a remporté le plus de titres consécutifs à Roland Garros?", listOf("Nadal", "Borg", "Sampras", "Federer"), 0, "Sport", Difficulty.MEDIUM, explanation = "Rafael Nadal détient le record avec cinq titres consécutifs à Roland Garros, de 2010 à 2014. Il est surnommé le \"Roi de la terre battue\" pour ses 14 victoires sur le tournoi."),
        Question(8074, "Combien de fois Nadal a-t-il remporté l'US Open?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.MEDIUM, explanation = "Rafael Nadal a remporté l'US Open à quatre reprises (2010, 2013, 2017, 2019), ce qui correspond à la bonne réponse."),
        Question(8075, "Quel est le record du nombre de points consécutifs gagnés en match de tennis?", listOf("5", "10", "15", "20"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 15 points consécutifs gagnés en tennis a été établi par Bill Scanlon lors du tournoi de Delray Beach en 1982, un exploit appelé \"Golden Set\" car il a remporté un set 6-0 sans perdre un point."),
        Question(8076, "En quelle année la Coupe Davis a-t-elle été créée?", listOf("1900", "1903", "1905", "1907"), 1, "Sport", Difficulty.HARD, explanation = "La Coupe Davis a été créée en 1900, mais la première édition officielle a eu lieu en 1903, année où le trophée a été remporté par les États-Unis."),
        Question(8077, "Qui a remporté le plus de titres Master 1000?", listOf("Roger Federer", "Novak Djokovic", "Rafael Nadal", "Andre Agassi"), 1, "Sport", Difficulty.HARD, explanation = "Novak Djokovic détient le record du nombre de titres en Masters 1000, avec 40 victoires, dépassant Rafael Nadal (36) et Roger Federer (28)."),
        Question(8078, "Combien de matchs consécutifs sans défaite Serena Williams a-t-elle enregistrés?", listOf("30", "31", "35", "40"), 1, "Sport", Difficulty.HARD, explanation = "Serena Williams a remporté 31 matchs consécutifs entre 2014 et 2015, égalant la plus longue série de l'ère Open pour une joueuse de tennis."),
        Question(8079, "Quel joueur a remporté le plus vite un Grand Slam?", listOf("Roger Federer", "Pete Sampras", "Stefanos Tsitsipas", "Novak Djokovic"), 0, "Sport", Difficulty.HARD, explanation = "Roger Federer a remporté son premier Grand Slam à Wimbledon en 2003, puis a atteint les dix titres majeurs en seulement cinq ans, un record de rapidité à l'époque."),
        Question(8080, "En quelle année Borg a-t-il remporté Wimbledon?", listOf("1976", "1978", "1980", "1981"), 1, "Sport", Difficulty.MEDIUM, explanation = "Björn Borg a remporté Wimbledon pour la première fois en 1976, mais la question fait référence à son titre de 1978, qui fut son troisième consécutif dans ce tournoi."),
        Question(8081, "Combien de fois Federer a-t-il remporté l'US Open?", listOf("4", "5", "6", "7"), 1, "Sport", Difficulty.MEDIUM, explanation = "Roger Federer a remporté l'US Open à cinq reprises, en 2004, 2005, 2006, 2007 et 2008, réalisant un quintuplé historique dans le tournoi new-yorkais."),
        Question(8082, "Quel est le plus grand nombre de sets remportés consécutivement?", listOf("20", "25", "30", "35"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 30 sets consécutifs est détenu par la joueuse de tennis Martina Navratilova, qui a réalisé cette performance en 1983-1984."),
        Question(8083, "Qui a remporté le plus de titres ATP 500?", listOf("Roger Federer", "Novak Djokovic", "Rafael Nadal", "Lleyton Hewitt"), 0, "Sport", Difficulty.HARD, explanation = "Roger Federer détient le record du nombre de titres ATP 500 avec 24 victoires, devant Rafael Nadal (23) et Novak Djokovic (15)."),
        Question(8084, "En quelle année Agassi a-t-il remporté le Grand Chelem en carrière?", listOf("1994", "1999", "2003", "2004"), 1, "Sport", Difficulty.HARD, explanation = "Andre Agassi a complété le Grand Chelem en carrière en 1999 en remportant Roland-Garros, le seul tournoi majeur qui lui manquait, après ses victoires à Wimbledon, l'Open d'Australie et l'US Open."),
        Question(8085, "Combien de matchs à Wimbledon Federer a-t-il remportés consécutivement?", listOf("30", "35", "40", "45"), 3, "Sport", Difficulty.HARD, explanation = "Roger Federer a remporté 45 matchs consécutifs à Wimbledon entre 2003 et 2008, une série qui inclut cinq titres consécutifs (2003-2007) et s'est achevée en finale 2008 face à Rafael Nadal."),
        Question(8086, "Quel joueur a le meilleur record à Roland Garros?", listOf("Federer", "Djokovic", "Nadal", "Murray"), 2, "Sport", Difficulty.EASY, explanation = "Rafael Nadal détient le record du nombre de victoires à Roland-Garros avec quatorze titres, un record inégalé dans l'histoire du tournoi."),
        Question(8087, "En quelle année Nadal a-t-il remporté son premier Roland Garros?", listOf("2003", "2004", "2005", "2006"), 2, "Sport", Difficulty.MEDIUM, explanation = "Rafael Nadal a remporté son premier titre à Roland-Garros en 2005 à seulement 19 ans, battant Mariano Puerta en finale. Ce fut le début de sa domination sans précédent sur la terre battue parisienne."),
        Question(8088, "Combien de fois Federer a-t-il remporté Wimbledon?", listOf("7", "8", "9", "10"), 1, "Sport", Difficulty.MEDIUM, explanation = "Roger Federer a remporté Wimbledon à huit reprises, un record masculin, entre 2003 et 2017. Il a notamment réalisé une série de cinq victoires consécutives de 2003 à 2007."),
        Question(8089, "Qui a remporté le plus de matchs de tennis professionnel?", listOf("Roger Federer", "Jimmy Connors", "Ivan Lendl", "Pete Sampras"), 1, "Sport", Difficulty.HARD, explanation = "Jimmy Connors détient le record du nombre de matchs gagnés en simple dans l'ère Open, avec 1 274 victoires en carrière."),
        Question(8090, "En quelle année Martina Navratilova a-t-elle pris sa retraite?", listOf("1994", "2000", "2006", "2011"), 0, "Sport", Difficulty.HARD, explanation = "Martina Navratilova, légende du tennis, a mis fin à sa carrière professionnelle en 1994 après avoir remporté 18 titres du Grand Chelem en simple."),
        Question(8091, "Combien de fois le tennis a-t-il été une discipline olympique?", listOf("Depuis 1896", "Depuis 1920", "Depuis 1968", "Depuis 1988"), 3, "Sport", Difficulty.HARD, explanation = "Le tennis a été réintroduit comme discipline olympique en 1988 aux Jeux de Séoul, après avoir été absent du programme depuis 1924."),
        Question(8092, "Quel est le nombre de matchs disputés dans un tournoi Grand Slam?", listOf("64", "127", "128", "256"), 1, "Sport", Difficulty.MEDIUM, explanation = "Dans un tournoi du Grand Chelem, 128 joueurs s'affrontent en simple, et chaque match élimine un joueur, donc 127 matchs sont nécessaires pour désigner le vainqueur."),
        Question(8093, "En quelle année Sampras a-t-il remporté son premier Wimbledon?", listOf("1993", "1994", "1995", "1997"), 1, "Sport", Difficulty.HARD, explanation = "Pete Sampras a remporté son premier tournoi de Wimbledon en 1993, pas en 1994. Il a battu Jim Courier en finale en 1993, puis a défendu son titre avec succès en 1994."),
        Question(8094, "Qui a remporté le plus de titres WTA 1000?", listOf("Serena Williams", "Venus Williams", "Maria Sharapova", "Venus Williams"), 0, "Sport", Difficulty.HARD, explanation = "Serena Williams détient le record de titres WTA 1000 avec 23 victoires dans cette catégorie, surpassant Venus Williams et Martina Navratilova."),
        Question(8095, "Combien de fois Connors a-t-il remporté l'US Open?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.MEDIUM, explanation = "Jimmy Connors a remporté l'US Open à cinq reprises (1974, 1976, 1978, 1982, 1983), et non deux fois."),
        Question(8096, "Quel est le record du number one du classement ATP?", listOf("Federer 302 semaines", "Djokovic 400 semaines", "Connors 268 semaines", "Murray 34 semaines"), 1, "Sport", Difficulty.HARD, explanation = "Novak Djokovic détient le record du plus grand nombre de semaines passées à la première place du classement ATP, avec plus de 400 semaines, surpassant ainsi les précédents records de Roger Federer et Pete Sampras."),
        Question(8097, "En quelle année McEnroe a-t-il remporté Wimbledon?", listOf("1981", "1983", "1984", "1985"), 0, "Sport", Difficulty.MEDIUM, explanation = "John McEnroe a remporté Wimbledon en 1981 en battant Bjorn Borg en finale, mettant fin à la série de cinq titres consécutifs de ce dernier."),
        Question(8098, "Qui a remporté le plus de titres consécutifs dans un tournoi?", listOf("Federer", "Djokovic", "Nadal", "Murray"), 2, "Sport", Difficulty.HARD, explanation = "Rafael Nadal détient le record de titres consécutifs dans un même tournoi avec 9 victoires à Roland-Garros entre 2005 et 2014."),
        Question(8099, "Combien de fois Henin a-t-elle remporté Roland Garros?", listOf("2", "3", "4", "5"), 2, "Sport", Difficulty.HARD, explanation = "Justine Henin a remporté Roland-Garros à quatre reprises en 2003, 2005, 2006 et 2007, ce qui constitue un record pour une joueuse belge sur ce tournoi."),

        // Basketball (101-150)
        Question(8100, "Combien de championships NBA Michael Jordan a-t-il remportés?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.EASY, explanation = "Michael Jordan a remporté six titres NBA avec les Chicago Bulls, lors de deux séries de trois victoires consécutives entre 1991 et 1998."),
        Question(8101, "Quel joueur a marqué le plus de points en carrière NBA?", listOf("Kareem Abdul-Jabbar", "Karl Malone", "LeBron James", "Kobe Bryant"), 2, "Sport", Difficulty.MEDIUM, explanation = "LeBron James a dépassé Kareem Abdul-Jabbar en février 2023 pour devenir le meilleur marqueur de l'histoire de la NBA, totalisant plus de 40 000 points en carrière."),
        Question(8102, "Combien de points Kareem Abdul-Jabbar a-t-il marqués en carrière?", listOf("38387", "39000", "40000", "38000"), 0, "Sport", Difficulty.HARD, explanation = "Kareem Abdul-Jabbar a détenu le record de points en NBA pendant près de 40 ans, avec 38 387 points marqués en carrière, avant d'être dépassé par LeBron James en 2023."),
        Question(8103, "Quel équipe a remporté le plus de championships NBA?", listOf("Lakers", "Celtics", "Bulls", "Warriors"), 1, "Sport", Difficulty.MEDIUM, explanation = "Les Celtics de Boston détiennent le record avec 18 titres NBA, dont huit consécutifs de 1959 à 1966 sous la direction de Red Auerbach."),
        Question(8104, "En quelle année la NBA a-t-elle été fondée?", listOf("1946", "1950", "1954", "1960"), 0, "Sport", Difficulty.HARD, explanation = "La NBA a été fondée en 1946 sous le nom de Basketball Association of America (BAA) avant de fusionner avec la National Basketball League en 1949 pour devenir la NBA."),
        Question(8105, "Combien de fois LeBron James a-t-il changé d'équipe?", listOf("1", "2", "3", "4"), 3, "Sport", Difficulty.MEDIUM, explanation = "LeBron James a joué pour les Cleveland Cavaliers, le Miami Heat, les Los Angeles Lakers et de nouveau les Cavaliers, effectuant quatre changements d'équipe au total en 2024."),
        Question(8106, "Quel est le record du plus grand nombre de points en un match NBA?", listOf("69", "70", "71", "72"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le record est détenu par Wilt Chamberlain avec 100 points en 1962. La réponse 70 est incorrecte, car plusieurs joueurs ont dépassé ce total, dont Kobe Bryant avec 81 points en 2006."),
        Question(8107, "Qui a marqué 70 points en un match NBA?", listOf("Wilt Chamberlain", "Michael Jordan", "Kobe Bryant", "LeBron James"), 2, "Sport", Difficulty.HARD, explanation = "Kobe Bryant a inscrit 70 points lors d'un match des Lakers contre les Raptors en 2006, un exploit rare dans l'histoire de la NBA."),
        Question(8108, "Combien de fois les Lakers ont-ils remporté le championship?", listOf("15", "16", "17", "18"), 2, "Sport", Difficulty.MEDIUM, explanation = "Les Lakers de Los Angeles ont remporté 17 titres NBA, à égalité avec les Celtics de Boston pour le record de la ligue. Leur dernier championnat date de 2020."),
        Question(8109, "Quel joueur a remporté le plus d'MVP NBA?", listOf("Wilt Chamberlain", "Bill Russell", "Kareem Abdul-Jabbar", "Michael Jordan"), 2, "Sport", Difficulty.HARD, explanation = "Kareem Abdul-Jabbar a remporté six titres de MVP NBA, un record qu'il détient seul depuis 1974, devant Bill Russell et Michael Jordan qui en comptent cinq chacun."),
        Question(8110, "En quelle année Shaquille O'Neal a-t-il remporté son premier championship?", listOf("1999", "2000", "2001", "2002"), 1, "Sport", Difficulty.MEDIUM, explanation = "Shaquille O'Neal a remporté son premier titre NBA en 2000 avec les Los Angeles Lakers, marquant le début de leur triplé historique (2000-2002)."),
        Question(8111, "Combien de fois Tim Duncan a-t-il remporté le championship?", listOf("3", "4", "5", "6"), 2, "Sport", Difficulty.MEDIUM, explanation = "Tim Duncan a remporté cinq titres NBA avec les San Antonio Spurs en 1999, 2003, 2005, 2007 et 2014."),
        Question(8112, "Quel est le record du plus grand nombre de rebonds en un match?", listOf("50", "55", "60", "65"), 2, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par Wilt Chamberlain, qui a capté 60 rebonds lors d'un match de NBA en 1960. Il s'agit du plus haut total jamais enregistré dans l'histoire de la ligue."),
        Question(8113, "Qui a enregistré le triple-double avec le plus de points?", listOf("Oscar Robertson", "Magic Johnson", "LeBron James", "Russell Westbrook"), 2, "Sport", Difficulty.HARD, explanation = "LeBron James détient le record du triple-double avec le plus de points en NBA, avec 51 points lors d'un match en 2018 contre les Wizards."),
        Question(8114, "Combien de fois Bill Russell a-t-il remporté le championship?", listOf("10", "11", "12", "13"), 1, "Sport", Difficulty.HARD, explanation = "Bill Russell a remporté 11 championnats NBA avec les Boston Celtics entre 1957 et 1969, un record toujours inégalé dans l'histoire de la ligue."),
        Question(8115, "En quelle année la NBA a-t-elle intégré des joueurs noirs?", listOf("1950", "1952", "1954", "1956"), 1, "Sport", Difficulty.HARD, explanation = "La NBA a intégré ses premiers joueurs noirs en 1950, mais c'est en 1952 que la ligue a officiellement levé la barrière raciale en permettant à tous les joueurs, quelle que soit leur couleur de peau, de participer."),
        Question(8116, "Quel joueur a le plus grand nombre de passes décisives en carrière?", listOf("Magic Johnson", "John Stockton", "Karl Malone", "LeBron James"), 1, "Sport", Difficulty.HARD, explanation = "John Stockton détient le record de passes décisives en NBA avec 15 806, une marque jamais approchée, fruit de ses 19 saisons avec le Utah Jazz."),
        Question(8117, "Combien de fois Stephen Curry a-t-il remporté le MVP?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.MEDIUM, explanation = "Stephen Curry a été élu MVP de la NBA en 2015 et 2016, devenant le premier joueur de l'histoire à recevoir l'unanimité des votes pour ce titre en 2016."),
        Question(8118, "Quel est le record du plus grand nombre de tirs à 3 points en un match?", listOf("12", "13", "14", "15"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus grand nombre de tirs à 3 points réussis en un match NBA est de 14, détenu par Klay Thompson (2018) et Stephen Curry (2016 et 2023)."),
        Question(8119, "En quelle année le Jazz a-t-il failli remporter le championship?", listOf("1997", "1998", "1999", "2000"), 2, "Sport", Difficulty.HARD, explanation = "Le Jazz de l'Utah a atteint la finale NBA en 1997 et 1998, mais a perdu les deux fois contre les Bulls de Chicago. En 1999, ils ont été éliminés au deuxième tour des playoffs par les Trail Blazers de Portland."),
        Question(8120, "Combien de fois Nikola Jokic a-t-il remporté l'MVP?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.MEDIUM, explanation = "Nikola Jokic a été élu MVP de la NBA en 2021 et 2022, remportant le titre deux fois consécutives avec les Denver Nuggets."),
        Question(8121, "Quel joueur a le meilleur pourcentage de tirs en carrière?", listOf("Deandre Jordan", "DeAndre Ayton", "Mark Gasol", "Nene"), 1, "Sport", Difficulty.HARD, explanation = "DeAndre Ayton détient le meilleur pourcentage de tirs en carrière en NBA (minimum 2000 tirs tentés) grâce à son efficacité près du panier et son jeu de finition dominant."),
        Question(8122, "En quelle année les Warriors ont-ils remporté 73 victoires?", listOf("2014", "2015", "2016", "2017"), 2, "Sport", Difficulty.MEDIUM, explanation = "Les Golden State Warriors ont battu le record des Bulls de 72 victoires en 1996 en atteignant 73 victoires lors de la saison régulière 2015-2016 de la NBA."),
        Question(8123, "Combien de points Wilt Chamberlain a-t-il marqués en carrière?", listOf("30000", "31000", "31419", "32000"), 2, "Sport", Difficulty.HARD, explanation = "Wilt Chamberlain a marqué 31 419 points en carrière NBA, un total qui le place au septième rang des meilleurs marqueurs de l'histoire. Il est surtout connu pour son record de 100 points en un seul match en 1962."),
        Question(8124, "Quel est le record du plus grand nombre de points en trois quarts-temps?", listOf("50", "55", "60", "65"), 2, "Sport", Difficulty.HARD, explanation = "Ce record a été établi par Klay Thompson des Golden State Warriors en 2016, marquant 60 points en seulement 29 minutes de jeu contre les Indiana Pacers."),
        Question(8125, "En quelle année le Heat a-t-il remporté le championship?", listOf("2011", "2012", "2013", "2014"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le Miami Heat a remporté le championnat NBA en 2013 en battant les San Antonio Spurs en sept matchs lors des finales, avec LeBron James élu MVP des finales."),
        Question(8126, "Combien de fois Hakeem Olajuwon a-t-il remporté le championship?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.MEDIUM, explanation = "Hakeem Olajuwon a remporté deux championnats NBA avec les Houston Rockets, en 1994 et 1995."),
        Question(8127, "Quel joueur a le plus grand nombre d'interceptions en carrière?", listOf("Michael Jordan", "Karl Malone", "Charles Barkley", "John Havlicek"), 0, "Sport", Difficulty.HARD, explanation = "Michael Jordan détient le record du plus grand nombre d'interceptions en carrière en NBA, avec 2 514 interceptions, grâce à sa défense exceptionnelle et ses réflexes rapides."),
        Question(8128, "En quelle année the three-point line a-t-elle été adoptée?", listOf("1979", "1980", "1981", "1982"), 0, "Sport", Difficulty.HARD, explanation = "La ligne à trois points a été introduite en NBA lors de la saison 1979-1980, après un essai dans l'American Basketball Association (ABA) dans les années 1960."),
        Question(8129, "Combien de fois Kevin Durant a-t-il remporté le score title?", listOf("1", "2", "3", "4"), 3, "Sport", Difficulty.MEDIUM, explanation = "Kevin Durant a mené la NBA au scoring quatre fois, en 2010, 2011, 2012 et 2014, toutes avec le Thunder d'Oklahoma City."),
        Question(8130, "Quel est le record du plus grand nombre de passes décisives en un match?", listOf("20", "21", "22", "25"), 1, "Sport", Difficulty.HARD, explanation = "Le record de 21 passes décisives en un match a été établi par Scottie Pippen lors d'un match de NBA en 1994, un record qui tient toujours dans l'histoire de la ligue."),
        Question(8131, "En quelle année le Spurs a-t-il remporté son premier championship?", listOf("1997", "1999", "2001", "2003"), 1, "Sport", Difficulty.MEDIUM, explanation = "Les San Antonio Spurs ont remporté leur premier titre NBA en 1999, en battant les New York Knicks en finale. Cette victoire marquait le début de l'ère Tim Duncan sous la direction de Gregg Popovich."),
        Question(8132, "Combien de fois Malone a-t-il remporté le MVP?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.MEDIUM, explanation = "Karl Malone a remporté le titre de MVP de la NBA à deux reprises, en 1997 et 1999, alors qu'il jouait pour le Utah Jazz."),
        Question(8133, "Quel joueur a le plus grand nombre de steals en carrière?", listOf("Michael Jordan", "John Stockton", "Karl Malone", "Charles Barkley"), 1, "Sport", Difficulty.HARD, explanation = "John Stockton détient le record NBA de steals en carrière avec 3 265 interceptions, une marque qu'il a établie durant ses 19 saisons avec le Utah Jazz."),
        Question(8134, "En quelle année l'ABA a-t-elle fusionné avec la NBA?", listOf("1974", "1976", "1978", "1980"), 1, "Sport", Difficulty.HARD, explanation = "L'American Basketball Association (ABA) a cessé ses activités et quatre de ses équipes ont rejoint la NBA en 1976, marquant la fin de la rivalité entre les deux ligues."),
        Question(8135, "Combien de fois Isaiah Thomas a-t-il remporté le championship?", listOf("0", "1", "2", "3"), 0, "Sport", Difficulty.HARD, explanation = "Isaiah Thomas n'a jamais gagné de titre NBA, malgré une carrière marquée par des performances individuelles remarquables comme ses 53 points en playoffs 2017."),
        Question(8136, "Quel est le record du plus grand nombre de points en demi-finale?", listOf("60", "65", "70", "75"), 1, "Sport", Difficulty.HARD, explanation = "Le record de 65 points en demi-finale a été établi par Michael Jordan lors du match 4 des playoffs NBA 1986 contre les Celtics de Boston."),
        Question(8137, "En quelle année Magic Johnson et Bird ont-ils commencé leur rivalité?", listOf("1979", "1980", "1981", "1982"), 1, "Sport", Difficulty.MEDIUM, explanation = "Magic Johnson et Larry Bird se sont affrontés pour la première fois en finale NCAA en 1979, mais leur rivalité légendaire en NBA a débuté en 1980 lors des Finales NBA, où les Lakers de Johnson ont battu les Celtics de Bird."),
        Question(8138, "Combien de fois Pat Riley a-t-il remporté le championship en tant que joueur?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.HARD, explanation = "Pat Riley a remporté le titre NBA en 1972 avec les Los Angeles Lakers, puis en 1980 et 1982 en tant que joueur des Lakers, totalisant trois championnats."),
        Question(8139, "Quel joueur a le meilleur pourcentage de tirs libres en carrière?", listOf("Ray Allen", "Steve Nash", "Steph Curry", "Kevin Durant"), 1, "Sport", Difficulty.HARD, explanation = "Steve Nash détient le record du meilleur pourcentage de lancers francs en carrière en NBA avec 90,4%, devant Mark Price et Stephen Curry."),
        Question(8140, "En quelle année le All-Star Game a-t-il commencé?", listOf("1949", "1951", "1953", "1955"), 1, "Sport", Difficulty.HARD, explanation = "Le premier All-Star Game de la NBA a eu lieu en 1951 au Boston Garden, opposant les meilleurs joueurs de la conférence Est à ceux de la conférence Ouest."),
        Question(8141, "Combien de fois Scottie Pippen a-t-il remporté le championship?", listOf("5", "6", "7", "8"), 1, "Sport", Difficulty.MEDIUM, explanation = "Scottie Pippen a remporté six titres NBA avec les Chicago Bulls, tous aux côtés de Michael Jordan, lors des saisons 1990-1991, 1991-1992, 1992-1993, 1995-1996, 1996-1997 et 1997-1998."),
        Question(8142, "Quel est le record du plus grand nombre de rebonds en une saison?", listOf("1500", "1600", "1700", "1800"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 1700 rebonds en une saison NBA a été établi par Wilt Chamberlain en 1961-1962, une performance inégalée depuis."),
        Question(8143, "En quelle année le Draft NBA a-t-il commencé?", listOf("1961", "1963", "1965", "1967"), 1, "Sport", Difficulty.HARD, explanation = "Le premier repêchage de la NBA a eu lieu en 1947, mais c'est en 1963 que le système moderne, avec des tours de sélection et un ordre basé sur les classements, a été officiellement adopté."),
        Question(8144, "Combien de fois Dennis Rodman a-t-il remporté le rebounding title?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.HARD, explanation = "Dennis Rodman a mené la NBA au rebond pendant sept saisons consécutives, de 1992 à 1998, un record pour un joueur non-pivot."),
        Question(8145, "Quel joueur a le plus grand nombre de blocks en carrière?", listOf("Dikembe Mutombo", "Kareem Abdul-Jabbar", "Hakeem Olajuwon", "Mark Eaton"), 2, "Sport", Difficulty.HARD, explanation = "Hakeem Olajuwon détient le record de blocks en carrière avec 3 830, devant Dikembe Mutombo. Il était réputé pour son agilité défensive et son timing exceptionnel sous le panier."),
        Question(8146, "En quelle année Jordan a-t-il remporté son premier MVP?", listOf("1987", "1988", "1989", "1991"), 1, "Sport", Difficulty.MEDIUM, explanation = "Michael Jordan a remporté son premier titre de MVP de la saison régulière en 1988, après une saison exceptionnelle où il a mené la ligue au scoring et été élu défenseur de l'année."),
