        // Rugby (251-300)
        Question(8250, "Combien de fois la Nouvelle-Zélande a-t-elle remporté la Coupe du Monde de rugby?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.MEDIUM, explanation = "Les All Blacks ont remporté la Coupe du Monde de rugby à trois reprises : en 1987, 2011 et 2015."),
        Question(8251, "Quel pays a remporté la Coupe du Monde de rugby 2019?", listOf("Afrique du Sud", "Angleterre", "Nouvelle-Zélande", "Japon"), 0, "Sport", Difficulty.MEDIUM, explanation = "L'Afrique du Sud a battu l'Angleterre en finale (32-12) au Japon, décrochant ainsi son troisième titre mondial après 1995 et 2007."),
