        Question(8254, "Quel pays a remporté le Rugby World Cup 2023?", listOf("Nouvelle-Zélande", "Afrique du Sud", "Angleterre", "France"), 1, "Sport", Difficulty.MEDIUM, explanation = "L'Afrique du Sud a battu la Nouvelle-Zélande 12-11 en finale, remportant ainsi son quatrième titre mondial de rugby, un record."),
        Question(8255, "Combien de fois l'Afrique du Sud a-t-elle remporté la Coupe du Monde de rugby?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.MEDIUM, explanation = "L'Afrique du Sud a remporté la Coupe du Monde de rugby à trois reprises : en 1995, 2007 et 2019, ce qui en fait l'une des nations les plus titrées de la compétition."),
        Question(8256, "Quel est le plus grand tournoi de rugby annuel?", listOf("Six Nations", "Rugby Championship", "Pacific Nations Cup", "Americas Rugby Championship"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le Tournoi des Six Nations est la compétition annuelle de rugby la plus prestigieuse, opposant l'Angleterre, l'Écosse, le pays de Galles, l'Irlande, la France et l'Italie."),
        Question(8257, "Combien de nations participent aux Six Nations?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.EASY, explanation = "Le tournoi des Six Nations oppose traditionnellement six équipes nationales européennes de rugby : l'Angleterre, l'Écosse, le Pays de Galles, l'Irlande, la France et l'Italie."),
