        Question(8260, "Combien de matchs internationaux Richie McCaw a-t-il disputés?", listOf("130", "138", "148", "158"), 1, "Sport", Difficulty.HARD, explanation = "Richie McCaw a disputé 148 matchs pour les All Blacks, mais seulement 138 sont officiellement reconnus comme test matchs internationaux par World Rugby."),
        Question(8261, "Quel est le record du nombre de points en match international?", listOf("36", "42", "48", "54"), 1, "Sport", Difficulty.HARD, explanation = "Le record du nombre de points marqués par un joueur en match international de rugby est de 42 points, établi par l'Anglais Jonny Wilkinson contre l'Italie en 2001."),
