        Question(8263, "Quel est le record du nombre d'essais en match international?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.HARD, explanation = "Le record de six essais en match international a été établi par le Néo-Zélandais Marc Ellis contre le Japon en 1995, puis égalé par plusieurs joueurs dont l'Australien Chris Latham en 2004."),
