        Question(8265, "Combien de fois les All Blacks ont-ils remporté la Coupe du Monde?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.EASY, explanation = "Les All Blacks ont gagné la Coupe du Monde de rugby à trois reprises : en 1987 (première édition), 2011 et 2015."),
        Question(8266, "En quelle année le premier Rugby World Cup a-t-il eu lieu?", listOf("1985", "1987", "1989", "1991"), 1, "Sport", Difficulty.HARD, explanation = "La première Coupe du monde de rugby s'est déroulée en 1987, co-organisée par la Nouvelle-Zélande et l'Australie, et remportée par les All Blacks."),
        Question(8267, "Quel pays a remporté le premier Rugby World Cup?", listOf("Nouvelle-Zélande", "Australie", "France", "Afrique du Sud"), 1, "Sport", Difficulty.HARD, explanation = "La première Coupe du monde de rugby a eu lieu en 1987, co-organisée par l'Australie et la Nouvelle-Zélande. L'Australie a battu la France en finale pour remporter le titre inaugural."),
        Question(8268, "Combien de fois la France a-t-elle remporté la Coupe du Monde de rugby?", listOf("0", "1", "2", "3"), 0, "Sport", Difficulty.EASY, explanation = "La France n'a jamais remporté la Coupe du Monde de rugby, malgré trois finales perdues en 1987, 1999 et 2011."),
        Question(8269, "Quel est le Tri-Nations devenu?", listOf("Rugby Championship", "Pacific Nations Cup", "Americas Rugby Championship", "Nations League"), 0, "Sport", Difficulty.MEDIUM, explanation = "En 2012, le Tri-Nations, qui opposait l'Afrique du Sud, la Nouvelle-Zélande et l'Australie, s'est élargi avec l'ajout de l'Argentine pour devenir le Rugby Championship."),
        Question(8270, "Combien de pays participent au Rugby Championship?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le Rugby Championship réunit les quatre grandes nations de l'hémisphère sud : l'Afrique du Sud, l'Australie, la Nouvelle-Zélande et l'Argentine, depuis l'adhésion de cette dernière en 2012."),
        Question(8271, "Quel est le plus grand nombre de points marqués en Test match?", listOf("91", "100", "109", "120"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 109 points a été établi par la Nouvelle-Zélande contre le Japon en 1995, marquant la plus large victoire en Test match de rugby."),
        Question(8272, "Qui a marqué 109 points en Test match?", listOf("Gavin Henson", "Jonny Wilkinson", "Percy Montgomery", "Beauden Barrett"), 2, "Sport", Difficulty.HARD, explanation = "Percy Montgomery, arrière sud-africain, détient le record du plus grand nombre de points marqués en Test matchs avec 109, grâce à sa précision au pied lors des tournées de 2007."),
        Question(8273, "Combien de fois l'Angleterre a-t-elle remporté le Grand Chelem au Six Nations?", listOf("8", "10", "12", "14"), 2, "Sport", Difficulty.HARD, explanation = "L'Angleterre a remporté le Grand Chelem dans le Tournoi des Six Nations (et son prédécesseur, le Cinq Nations) à 12 reprises, la dernière fois en 2016."),
