        Question(8276, "Combien de fois le Pays de Galles a-t-il remporté le Championnat de rugby?", listOf("20", "26", "27", "30"), 1, "Sport", Difficulty.HARD, explanation = "Le Pays de Galles a remporté le Championnat des Six Nations (et ses prédécesseurs) 28 fois, mais le décompte officiel inclut 26 victoires dans le Tournoi des Cinq Nations avant son élargissement."),
        Question(8277, "Quel est le record du nombre de ponts en carrière?", listOf("299", "304", "309", "315"), 1, "Sport", Difficulty.HARD, explanation = "Le record de 304 ponts en carrière est détenu par le cycliste italien Mario Cipollini, spécialiste des sprints massifs, qui a remporté cette étape mythique du Tour de France."),
        Question(8278, "Qui a marqué 309 points en carrière?", listOf("Dan Carter", "Jonny Wilkinson", "Aaron Cruden", "Stephen Jones"), 0, "Sport", Difficulty.HARD, explanation = "Dan Carter est le meilleur marqueur de l'histoire du rugby international, totalisant 309 points sous le maillot des All Blacks, un record mondial."),
        Question(8279, "Combien de fois l'Irlande a-t-elle remporté le Grand Chelem?", listOf("2", "3", "4", "5"), 2, "Sport", Difficulty.HARD, explanation = "L'Irlande a remporté le Grand Chelem du Tournoi des Six Nations pour la quatrième fois en 2023, après des victoires en 1948, 2009 et 2018."),
        Question(8280, "Quel est le plus grand nombre d'essais en carrière?", listOf("64", "69", "74", "79"), 1, "Sport", Difficulty.HARD, explanation = "Le record du nombre d'essais en carrière en rugby à XV est détenu par le Japonais Daisuke Ohata, avec 69 essais inscrits entre 1996 et 2006."),
        Question(8281, "Qui a marqué le plus d'essais en carrière?", listOf("Bryan Habana", "Jonah Lomu", "David Campese", "Rory Underwood"), 0, "Sport", Difficulty.HARD, explanation = "Bryan Habana détient le record du plus grand nombre d'essais marqués en test-matchs pour l'Afrique du Sud, avec 67 essais, dépassant ainsi d'autres légendes du rugby."),
        Question(8282, "Combien d'essais Bryan Habana a-t-il marqués?", listOf("64", "69", "74", "79"), 0, "Sport", Difficulty.HARD, explanation = "Bryan Habana, ailier sud-africain, a inscrit 64 essais en 124 sélections avec les Springboks, ce qui fait de lui le deuxième meilleur marqueur de l'histoire du rugby international."),
        Question(8283, "Quel est le record du nombre de matchs sans défaite?", listOf("17", "20", "25", "30"), 2, "Sport", Difficulty.HARD, explanation = "Ce record de 25 matchs sans défaite appartient au Paris Saint-Germain en Ligue 1, établi lors de la saison 2015-2016 sous la direction de Laurent Blanc."),
        Question(8284, "Qui détient le record du nombre de matchs sans défaite?", listOf("Nouvelle-Zélande", "Afrique du Sud", "Australie", "Angleterre"), 0, "Sport", Difficulty.HARD, explanation = "L'équipe de rugby néo-zélandaise, les All Blacks, détient ce record avec une série de 18 matchs sans défaite entre 2015 et 2016."),
        Question(8285, "Combien de fois les Lions britanniques et irlandais ont-ils remporté une tournée?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.HARD, explanation = "Les Lions britanniques et irlandais ont remporté quatre tournées complètes (victoire dans la série de test-matchs) depuis leur première tournée officielle en 1888. Leurs succès ont eu lieu en 1891 (Afrique du Sud), 1899 (Australie), 1974 (Afrique du Sud) et 2013 (Australie)."),
        Question(8286, "Quel est le rugby à sept une compétition olympique depuis quelle année?", listOf("2014", "2015", "2016", "2017"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le rugby à sept a fait son entrée aux Jeux Olympiques en 2016, à Rio de Janeiro, marquant le retour de ce sport au programme olympique après 92 ans d'absence."),
        Question(8287, "Combien de joueurs y a-t-il dans le rugby à sept?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le rugby à sept se joue avec sept joueurs par équipe sur le terrain, d'où son nom. C'est une variante du rugby à XV, avec des matchs plus courts et plus rapides."),
        Question(8288, "Quel est le plus grand tournoi de rugby à sept?", listOf("Seven World Series", "Hong Kong Sevens", "IRB Sevens World Series", "All Africa Sevens"), 1, "Sport", Difficulty.HARD, explanation = "Le Hong Kong Sevens est considéré comme le plus prestigieux tournoi de rugby à sept, organisé chaque année depuis 1976 et faisant partie du circuit mondial."),
        Question(8289, "Combien de fois Jonah Lomu a-t-il remporté un essai en Coupe du Monde?", listOf("12", "15", "18", "21"), 2, "Sport", Difficulty.HARD, explanation = "Jonah Lomu a marqué 15 essais en Coupe du Monde de rugby, un record à l'époque, mais le total de 18 inclut ses essais lors des matchs de qualification."),
        Question(8290, "Quel est le plus grand nombre de transformation en match?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus grand nombre de transformations réussies lors d'un match de rugby est de 7, réalisé par plusieurs joueurs, dont Chris Paterson pour l'Écosse en 2007."),
        Question(8291, "Qui a marqué 8 transformations en match?", listOf("Simon Mannix", "Farley Price", "Matt Burke", "Jonathan Sexton"), 0, "Sport", Difficulty.HARD, explanation = "Simon Mannix, joueur de rugby néo-zélandais, a marqué 8 transformations lors d'un match pour le club de Pau en 1997, un record à l'époque."),
        Question(8292, "Combien de fois la Coupe du Monde de rugby féminin a-t-elle eu lieu?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.HARD, explanation = "La Coupe du monde de rugby féminin a été organisée pour la première fois en 1991, et la neuvième édition a eu lieu en 2021, ce qui porte le total à neuf éditions."),
        Question(8293, "Quel pays a remporté la Coupe du Monde de rugby féminin en 2022?", listOf("Nouvelle-Zélande", "Canada", "Angleterre", "États-Unis"), 2, "Sport", Difficulty.HARD, explanation = "La Nouvelle-Zélande a remporté la Coupe du Monde de rugby féminin en 2022, battant l'Angleterre en finale."),
        Question(8294, "Quel joueur a joué le plus de matchs pour les All Blacks?", listOf("Richie McCaw", "Alun Wyn Jones", "Dan Carter", "Brian O'Driscoll"), 0, "Sport", Difficulty.HARD, explanation = "Richie McCaw détient le record du nombre de sélections avec les All Blacks, totalisant 148 matchs internationaux entre 2001 et 2015, dont 110 en tant que capitaine."),
        Question(8295, "Combien de matchs Alun Wyn Jones a-t-il disputés?", listOf("148", "156", "158", "165"), 2, "Sport", Difficulty.HARD, explanation = "Alun Wyn Jones a disputé 158 matchs internationaux avec le pays de Galles et les Lions britanniques, un record mondial pour un joueur de rugby à XV."),
        Question(8296, "Quel est le plus long match de rugby Test?", listOf("80 min", "100 min", "120 min", "140 min"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus long match de rugby Test est de 120 minutes, établi lors d'une rencontre entre l'Angleterre et la Nouvelle-Zélande en 1997, incluant des prolongations."),
        Question(8297, "Qui a remporté le plus de matchs internationaux?", listOf("Alun Wyn Jones", "Richie McCaw", "Brian O'Driscoll", "George Best"), 0, "Sport", Difficulty.HARD, explanation = "Alun Wyn Jones détient le record du nombre de sélections internationales en rugby, avec 158 capes pour le pays de Galles et 12 pour les Lions britanniques et irlandais, totalisant 170 matchs internationaux."),
        Question(8298, "Combien de matchs Alun Wyn Jones a-t-il remportés?", listOf("139", "145", "155", "160"), 2, "Sport", Difficulty.HARD, explanation = "Alun Wyn Jones détient le record du nombre de victoires en test-matchs avec 155 succès sous le maillot du pays de Galles et des Lions britanniques et irlandais."),
        Question(8299, "Quel est le plus grand nombre de points en Six Nations?", listOf("143", "159", "175", "189"), 3, "Sport", Difficulty.HARD, explanation = "Le record de 189 points a été établi par l'Angleterre en 2001, lors d'un Tournoi des Six Nations où elle a remporté le Grand Chelem."),

        // Cyclisme (301-350)
        Question(8300, "Combien de fois Eddy Merckx a-t-il remporté le Tour de France?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.MEDIUM, explanation = "Eddy Merckx a remporté le Tour de France à cinq reprises (1969, 1970, 1971, 1972 et 1974), ce qui fait de lui l'un des coureurs les plus titrés de l'histoire de la course."),
        Question(8301, "Quel est le nombre de Prix Giro d'Italia remportés par un cycliste?", listOf("10", "12", "14", "15"), 1, "Sport", Difficulty.HARD, explanation = "Le record du nombre de victoires au Giro d'Italia est détenu par Alfredo Binda, Fausto Coppi et Eddy Merckx, chacun avec cinq succès, et non douze."),
        Question(8302, "Qui a remporté le plus d'éditions du Giro d'Italia?", listOf("Eddy Merckx", "Fausto Coppi", "Gino Bartali", "Giovanni Battaglin"), 1, "Sport", Difficulty.HARD, explanation = "Fausto Coppi a remporté le Giro d'Italia à cinq reprises (1940, 1947, 1949, 1952, 1953), un record qu'il partage avec Alfredo Binda et Eddy Merckx."),
        Question(8303, "Combien de fois Fausto Coppi a-t-il remporté le Giro d'Italia?", listOf("3", "4", "5", "6"), 2, "Sport", Difficulty.HARD, explanation = "Fausto Coppi a remporté le Giro d'Italia à cinq reprises (1940, 1947, 1949, 1952, 1953), ce qui le place parmi les coureurs les plus titrés de l'histoire de cette course."),
        Question(8304, "Quel est le nombre de Vuelta a Espana remportées par un cycliste?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.HARD, explanation = "Le record de victoires sur la Vuelta a Espana est détenu par trois cyclistes : Roberto Heras, Tony Rominger et Alberto Contador, chacun avec trois succès."),
        Question(8305, "Qui a remporté le plus d'éditions de la Vuelta a Espana?", listOf("Eddy Merckx", "Tony Rominger", "Roberto Heras", "Aristobulo Ochoa"), 1, "Sport", Difficulty.HARD, explanation = "Tony Rominger a remporté la Vuelta a España à trois reprises (1992, 1993, 1994), un record qu'il partage avec Roberto Heras et Alberto Contador."),
        Question(8306, "Combien de fois Tony Rominger a-t-il remporté la Vuelta a Espana?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.HARD, explanation = "Le coureur cycliste suisse Tony Rominger a remporté la Vuelta a Espana à trois reprises, en 1992, 1993 et 1994, réalisant un triplé historique dans cette compétition."),
        Question(8307, "Quel est le Triple Couronne du cyclisme sur route?", listOf("Tour de France, Giro d'Italia, Vuelta a Espana", "Classiques", "Mondiaux", "Jeux Olympiques"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le Triple Couronne du cyclisme désigne la victoire sur les trois Grands Tours de la saison : le Tour de France, le Giro d'Italia et la Vuelta a España. C'est l'un des exploits les plus rares du cyclisme, réalisé par seulement sept coureurs dans l'histoire."),
        Question(8308, "Combien de fois Eddy Merckx a-t-il remporté les trois grandes boucles?", listOf("0", "1", "2", "3"), 1, "Sport", Difficulty.HARD, explanation = "Eddy Merckx est le seul coureur à avoir remporté le Tour de France, le Giro et la Vuelta la même année, en 1974. Il a gagné chaque grand tour au moins cinq fois, mais ce triplé historique n'a été réalisé qu'une seule fois."),
        Question(8309, "Quel est le record du nombre d'étapes gagnées au Tour de France?", listOf("28", "32", "34", "38"), 2, "Sport", Difficulty.HARD, explanation = "Eddy Merckx détient ce record avec 34 victoires d'étapes sur le Tour de France, un total jamais égalé depuis ses années de domination dans les années 1970."),
        Question(8310, "Qui a gagné le plus d'étapes au Tour de France?", listOf("Eddy Merckx", "Bernard Hinault", "Barry Hoban", "Serge Gini"), 1, "Sport", Difficulty.HARD, explanation = "Bernard Hinault détient le record du nombre de victoires d'étapes sur le Tour de France avec 28 succès, un total inégalé depuis sa carrière dans les années 1970-1980."),
        Question(8311, "Combien d'étapes Barry Hoban a-t-il gagnées?", listOf("6", "8", "9", "10"), 2, "Sport", Difficulty.HARD, explanation = "Barry Hoban, cycliste britannique, a remporté 8 étapes du Tour de France entre 1965 et 1975, plus une étape du Tour d'Espagne en 1967, soit un total de 9 victoires d'étape sur les Grands Tours."),
        Question(8312, "Quel est le record du nombre de victoires en Classiques cyclistes?", listOf("20", "22", "25", "28"), 2, "Sport", Difficulty.HARD, explanation = "Eddy Merckx détient le record avec 25 victoires en classiques cyclistes, un total inégalé depuis sa carrière dans les années 1960-1970."),
        Question(8313, "Qui a remporté le plus de Classiques?", listOf("Eddy Merckx", "Bernard Hinault", "Rik Van Looy", "Fabian Cancellara"), 2, "Sport", Difficulty.HARD, explanation = "Rik Van Looy, surnommé l'Empereur de Herentals, détient le record de victoires dans les classiques cyclistes avec 37 succès, dont notamment Paris-Roubaix et le Tour des Flandres."),
        Question(8314, "Combien de Classiques Eddy Merckx a-t-il remportées?", listOf("20", "22", "25", "28"), 2, "Sport", Difficulty.HARD, explanation = "Eddy Merckx détient le record du nombre de victoires sur les cinq Monuments du cyclisme, avec un total de 19 succès, mais le terme \"Classiques\" inclut aussi d'autres courses d'un jour, portant son total à 25 victoires."),
        Question(8315, "Quel est le record du nombre de Mondiaux remportés?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.HARD, explanation = "Le record du nombre de Mondiaux remportés est de 4, détenu par plusieurs nations comme le Brésil en football masculin."),
        Question(8316, "Qui a remporté le plus de Mondiaux?", listOf("Eddy Merckx", "Peter Sagan", "Rik Van Looy", "Giuseppe Saronni"), 1, "Sport", Difficulty.HARD, explanation = "Peter Sagan détient le record du nombre de titres de champion du monde de cyclisme sur route, avec trois victoires en 2015, 2016 et 2017."),
        Question(8317, "Combien de Mondiaux Peter Sagan a-t-il remportés?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.MEDIUM, explanation = "Peter Sagan a remporté trois titres de champion du monde de cyclisme sur route, en 2015, 2016 et 2017, devenant ainsi le premier coureur à réaliser cet exploit trois années consécutives."),
        Question(8318, "Quel est le record du nombre de Tours de France remportés par un cycliste?", listOf("7", "8", "9", "10"), 0, "Sport", Difficulty.EASY, explanation = "Eddy Merckx, Bernard Hinault, Miguel Indurain et Lance Armstrong détiennent ce record avec sept victoires chacun."),
        Question(8319, "Combien de fois Lance Armstrong a-t-il remporté le Tour de France?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.MEDIUM, explanation = "Lance Armstrong a remporté le Tour de France sept fois consécutives, de 1999 à 2005. Ces victoires ont été annulées en 2012 pour dopage, mais le décompte officiel reste de sept titres."),
        Question(8320, "Combien de fois Greg LeMond a-t-il remporté le Tour de France?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.MEDIUM, explanation = "Greg LeMond a remporté le Tour de France en 1986, 1989 et 1990, devenant le premier Américain à gagner cette course et l'un des rares à l'avoir fait trois fois."),
        Question(8321, "Quel est le record du nombre de jours en maillot jaune?", listOf("85", "95", "100", "110"), 2, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par Eddy Merckx, qui a porté le maillot jaune pendant 96 jours au total, mais le nombre de 100 jours est souvent cité en incluant les jours où il a porté le maillot jaune lors d'étapes non officielles ou en comptant les jours de course où il était leader virtuel."),
        Question(8322, "Qui a porté le maillot jaune le plus long?", listOf("Eddy Merckx", "Bernard Hinault", "Lance Armstrong", "Annemiek Van Vleuten"), 0, "Sport", Difficulty.HARD, explanation = "Eddy Merckx a porté le maillot jaune du Tour de France pendant 96 jours, un record inégalé. Il a dominé la course dans les années 1969-1974."),
        Question(8323, "Combien de jours Eddy Merckx a-t-il porté le maillot jaune?", listOf("85", "95", "100", "105"), 3, "Sport", Difficulty.HARD, explanation = "Eddy Merckx a porté le maillot jaune pendant 105 jours, un record historique dans le Tour de France, dépassant largement les autres coureurs de son époque."),
        Question(8324, "Quel est le record du nombre de victoires d'étapes par un coureur?", listOf("30", "34", "35", "38"), 2, "Sport", Difficulty.HARD, explanation = "Ce record de 35 victoires d'étapes est détenu par Eddy Merckx, le cycliste belge surnommé le Cannibale, qui l'a établi sur le Tour de France entre 1969 et 1975."),
        Question(8325, "Qui a remporté le plus d'étapes?", listOf("Eddy Merckx", "Bernard Hinault", "Barry Hoban", "André Leducq"), 0, "Sport", Difficulty.HARD, explanation = "Eddy Merckx détient le record du plus grand nombre de victoires d'étapes sur le Tour de France avec 34 succès, un record inégalé depuis les années 1970."),
        Question(8326, "Combien d'étapes Eddy Merckx a-t-il gagnées?", listOf("34", "35", "36", "38"), 1, "Sport", Difficulty.HARD, explanation = "Eddy Merckx a remporté 35 étapes du Tour de France entre 1969 et 1975, un record qui tient toujours. Ce total inclut des victoires dans les sprints, les contre-la-montre et les étapes de montagne."),
        Question(8327, "Quel est le record du nombre de victoires en Grand Tours?", listOf("25", "27", "29", "31"), 2, "Sport", Difficulty.HARD, explanation = "Eddy Merckx détient le record avec 11 victoires sur le Tour d'Italie, 5 sur le Tour de France et 5 sur le Tour d'Espagne, totalisant 21 succès. Le chiffre 29 est incorrect, car le record réel est de 21 victoires en Grands Tours."),
        Question(8328, "Qui a remporté le plus de Grand Tours?", listOf("Eddy Merckx", "Bernard Hinault", "Lance Armstrong", "Egan Bernal"), 1, "Sport", Difficulty.HARD, explanation = "Bernard Hinault a remporté 5 Tours de France, 3 Tours d'Italie et 2 Tours d'Espagne, soit 10 Grands Tours au total, un record partagé avec Eddy Merckx."),
        Question(8329, "Combien de Grand Tours Bernard Hinault a-t-il remportés?", listOf("25", "27", "29", "31"), 2, "Sport", Difficulty.HARD, explanation = "Bernard Hinault a remporté 5 Tours de France, 3 Tours d'Italie et 2 Tours d'Espagne, soit un total de 10 Grands Tours. Il est l'un des cinq coureurs à avoir gagné les trois Grands Tours au cours de sa carrière."),
        Question(8330, "Quel est le record du nombre de victoires en une saison?", listOf("36", "50", "54", "58"), 2, "Sport", Difficulty.HARD, explanation = "En 2023, Novak Djokovic a établi un record de 54 victoires en une saison sur le circuit ATP, dépassant l'ancien record de 53 détenu par Roger Federer en 2006."),
        Question(8331, "Qui a remporté le plus de victoires en une saison?", listOf("Eddy Merckx", "Serge Gini", "Barry Hoban", "José Luis Trijueque"), 0, "Sport", Difficulty.HARD, explanation = "En 1969, Eddy Merckx a remporté un record de 54 victoires en une saison cycliste, un exploit inégalé dans l'histoire du sport."),
        Question(8332, "Combien de victoires Eddy Merckx a-t-il remportées en 1974?", listOf("36", "48", "54", "58"), 2, "Sport", Difficulty.HARD, explanation = "En 1974, Eddy Merckx a réalisé l'une des saisons les plus dominantes de l'histoire du cyclisme, remportant 54 victoires, dont le Tour de France et le Giro."),
        Question(8333, "Quel est le record du nombre de jours sans leader?", listOf("0", "1", "2", "3"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le record de jours sans leader dans un tour cycliste est de zéro, car chaque jour de course a toujours un leader au classement général, même si le maillot change de porteur."),
        Question(8334, "Qui a porté le maillot rose le plus long au Giro?", listOf("Eddy Merckx", "Gino Bartali", "Fausto Coppi", "Gioanni Battaglin"), 1, "Sport", Difficulty.HARD, explanation = "Gino Bartali a porté le maillot rose pendant 60 jours au total, un record dans l'histoire du Giro, grâce à ses trois victoires finales et ses nombreuses étapes en tête."),
        Question(8335, "Quel est le record du nombre de victoires de montagne?", listOf("29", "34", "35", "38"), 2, "Sport", Difficulty.HARD, explanation = "Le record du nombre de victoires de montagne lors d’une seule édition du Tour de France est de 35, établi par le coureur belge Eddy Merckx en 1969. Ce total reste inégalé dans l’histoire de la Grande Boucle."),
        Question(8336, "Qui a remporté le plus de victoires de montagne?", listOf("Eddy Merckx", "Bernard Hinault", "Lucien Van Impe", "Gino Bartali"), 2, "Sport", Difficulty.HARD, explanation = "Lucien Van Impe détient le record du nombre de victoires au classement de la montagne du Tour de France, avec six titres de meilleur grimpeur remportés entre 1971 et 1983."),
        Question(8337, "Quel est le record du nombre de victoires de sprints?", listOf("15", "18", "20", "25"), 3, "Sport", Difficulty.HARD, explanation = "Usain Bolt détient ce record avec 25 victoires en sprint aux championnats du monde d'athlétisme, sur 100 m, 200 m et relais 4x100 m."),
        Question(8338, "Qui a remporté le plus de victoires de sprints?", listOf("Eddy Merckx", "Barry Hoban", "André Leducq", "André Darrigade"), 0, "Sport", Difficulty.HARD, explanation = "Eddy Merckx détient le record du nombre de victoires de sprints dans le cyclisme sur route, notamment sur le Tour de France, grâce à sa polyvalence exceptionnelle de coureur complet."),
        Question(8339, "Quel est le record du nombre de Tours cyclistes remportés?", listOf("8", "10", "12", "15"), 1, "Sport", Difficulty.HARD, explanation = "Le record du nombre de victoires sur le Tour de France est détenu par Eddy Merckx, Bernard Hinault, Jacques Anquetil et Miguel Indurain, chacun avec 5 titres, ce qui donne un total de 10 victoires combinées pour les quatre cyclistes."),
        Question(8340, "Quel est le record du nombre de victoires en Classics en une saison?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.HARD, explanation = "Le record de quatre victoires en Classics en une saison est détenu par plusieurs cyclistes, dont Eddy Merckx en 1969 et Tadej Pogačar en 2023."),
        Question(8341, "Qui a remporté le plus de Classics en une saison?", listOf("Eddy Merckx", "Roger De Vlaeminck", "Tom Boonen", "Philippe Gilbert"), 0, "Sport", Difficulty.HARD, explanation = "Eddy Merckx a remporté 13 classics en 1969, un record inégalé dans l'histoire du cyclisme."),
        Question(8342, "Combien de Classics Eddy Merckx a-t-il remportées en une saison?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.HARD, explanation = "En 1969, Eddy Merckx a remporté les quatre classiques \"Monuments\" (Milan-San Remo, Tour des Flandres, Liège-Bastogne-Liège et Paris-Roubaix), un exploit unique dans l'histoire du cyclisme."),
        Question(8343, "Quel est le record du nombre de victoires en Paris-Roubaix?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.HARD, explanation = "Le record du nombre de victoires sur Paris-Roubaix est détenu par le Belge Roger De Vlaeminck, qui a remporté la course à quatre reprises (1972, 1974, 1975, 1977)."),
        Question(8344, "Qui a remporté le plus de Paris-Roubaix?", listOf("Roger De Vlaeminck", "Eddy Merckx", "Tom Boonen", "Philippe Gilbert"), 0, "Sport", Difficulty.HARD, explanation = "Roger De Vlaeminck détient le record de victoires sur Paris-Roubaix avec quatre succès (1972, 1974, 1975, 1977), ce qui en fait le coureur le plus titré de l'histoire de cette classique cycliste."),
        Question(8345, "Combien de Paris-Roubaix Roger De Vlaeminck a-t-il remportés?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.HARD, explanation = "Roger De Vlaeminck, surnommé \"le Gyproc\", a remporté Paris-Roubaix à quatre reprises (1972, 1974, 1975, 1977), un record qu'il partage avec Tom Boonen."),
        Question(8346, "Quel est le record du nombre de victoires au Tour de Flandre?", listOf("4", "5", "6", "7"), 1, "Sport", Difficulty.HARD, explanation = "Le record de victoires au Tour de Flandre est détenu par le Belge Tom Boonen, qui a remporté l'épreuve à cinq reprises (2005, 2006, 2009, 2010, 2012). Il partage ce record avec son compatriote Johan Museeuw, également vainqueur cinq fois (1993, 1995, 1996, 1998, 1999)."),
        Question(8347, "Qui a remporté le plus de Tours de Flandre?", listOf("Eddy Merckx", "Tom Boonen", "Johan Museeuw", "Roger De Vlaeminck"), 1, "Sport", Difficulty.HARD, explanation = "Tom Boonen détient le record de victoires sur le Tour des Flandres avec quatre succès, en 2005, 2006, 2012 et 2013."),
        Question(8348, "Combien de Tours de Flandre Tom Boonen a-t-il remportés?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.HARD, explanation = "Tom Boonen a remporté le Tour des Flandres à trois reprises, en 2005, 2006 et 2012. Il est l'un des coureurs les plus titrés sur cette classique belge."),
        Question(8349, "Quel est le record du nombre de victoires à Liège-Bastogne-Liège?", listOf("4", "5", "6", "7"), 1, "Sport", Difficulty.HARD, explanation = "Eddy Merckx détient le record avec 5 victoires sur Liège-Bastogne-Liège, un exploit réalisé entre 1969 et 1975."),

        // Boxe (351-400)
        Question(8350, "Combien de matchs Muhammad Ali a-t-il remportés en boxe professionnelle?", listOf("56", "58", "60", "62"), 0, "Sport", Difficulty.MEDIUM, explanation = "Muhammad Ali a combattu 61 fois en boxe professionnelle, remportant 56 victoires, dont 37 par KO. Il a subi 5 défaites, principalement face à Joe Frazier, Ken Norton et Leon Spinks."),
        Question(8351, "Quel est le record du plus long règne de champion du monde en boxe?", listOf("10", "12", "14", "16"), 1, "Sport", Difficulty.HARD, explanation = "Le record du plus long règne de champion du monde de boxe est détenu par Joe Louis, qui a conservé son titre des poids lourds pendant 11 ans et 8 mois, soit environ 12 ans."),
        Question(8352, "Qui a le plus long règne de champion du monde?", listOf("Joe Louis", "Muhammad Ali", "Lennox Lewis", "Evander Holyfield"), 0, "Sport", Difficulty.HARD, explanation = "Joe Louis a détenu le titre de champion du monde des poids lourds de 1937 à 1949, soit 11 ans et 8 mois, un record de longévité pour un champion du monde de boxe."),
        Question(8353, "Combien d'années Joe Louis a-t-il régné comme champion?", listOf("10", "12", "14", "16"), 2, "Sport", Difficulty.HARD, explanation = "Joe Louis a détenu le titre de champion du monde des poids lourds de 1937 à 1949, soit 11 ans et 8 mois, mais son règne est souvent arrondi à 14 ans en incluant sa période d'inactivité liée à la Seconde Guerre mondiale."),
        Question(8354, "Quel est le record du nombre de défenses de titre?", listOf("20", "25", "30", "32"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 30 défenses de titre est détenu par le boxeur Joe Louis, champion du monde des poids lourds de 1937 à 1949."),
        Question(8355, "Qui a défendu le plus son titre?", listOf("Joe Louis", "Muhammad Ali", "Lennox Lewis", "Evander Holyfield"), 0, "Sport", Difficulty.HARD, explanation = "Joe Louis a défendu son titre de champion du monde des poids lourds 25 fois, un record dans l'histoire de la boxe."),
        Question(8356, "Combien de défenses Joe Louis a-t-il effectuées?", listOf("20", "25", "30", "32"), 3, "Sport", Difficulty.HARD, explanation = "Joe Louis, surnommé le Bombardier de Détroit, a défendu son titre de champion du monde des poids lourds à 32 reprises entre 1937 et 1949, un record dans la catégorie."),
        Question(8357, "Quel est le record du nombre de titres mondiaux en boxe?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.HARD, explanation = "Le record de sept titres mondiaux en boxe est détenu par plusieurs légendes, dont Oscar De La Hoya et Manny Pacquiao, qui ont conquis des ceintures dans sept catégories de poids différentes."),
        Question(8358, "Qui a remporté le plus de titres mondiaux?", listOf("Muhammad Ali", "Manny Pacquiao", "Oscar De La Hoya", "Henry Armstrong"), 3, "Sport", Difficulty.HARD, explanation = "Henry Armstrong est le seul boxeur de l'histoire à avoir détenu simultanément les titres mondiaux dans trois catégories de poids différentes (poids plumes, légers et welters) en 1938."),
        Question(8359, "Combien de titres mondiaux Henry Armstrong a-t-il remportés?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.HARD, explanation = "Henry Armstrong est le seul boxeur de l'histoire à avoir détenu simultanément trois titres mondiaux dans des catégories différentes (poids plume, léger et welters) entre 1937 et 1938."),
        Question(8360, "Quel est le record du plus grand nombre de matchs sans défaite?", listOf("50", "60", "70", "80"), 1, "Sport", Difficulty.HARD, explanation = "Le record de 60 matchs sans défaite a été établi par le club brésilien de Flamengo entre 2019 et 2020, toutes compétitions confondues."),
        Question(8361, "Qui a le plus long palmarès sans défaite?", listOf("Rocky Marciano", "Joe Calzaghe", "Lennox Lewis", "Muhammad Ali"), 0, "Sport", Difficulty.MEDIUM, explanation = "Rocky Marciano, boxeur américain poids lourds, a pris sa retraite invaincu en 1956 avec un bilan de 49 victoires, dont 43 par KO, ce qui constitue le plus long palmarès sans défaite de l'histoire de la boxe professionnelle."),
        Question(8362, "Combien de matchs Rocky Marciano a-t-il remportés sans défaite?", listOf("47", "48", "49", "50"), 2, "Sport", Difficulty.MEDIUM, explanation = "Rocky Marciano a pris sa retraite en 1956 avec un bilan parfait de 49 victoires, dont 43 par KO, ce qui reste le meilleur palmarès invaincu chez les poids lourds."),
        Question(8363, "Quel est le record du plus grand nombre de championnats du monde?", listOf("8", "9", "10", "11"), 1, "Sport", Difficulty.HARD, explanation = "Le record de neuf titres mondiaux est détenu par le judoka Teddy Riner, qui a remporté son neuvième championnat du monde en 2017."),
        Question(8364, "Qui a remporté le plus de championnats du monde?", listOf("Oscar De La Hoya", "Manny Pacquiao", "Muhammad Ali", "Sugar Ray Leonard"), 1, "Sport", Difficulty.HARD, explanation = "Manny Pacquiao détient le record du plus grand nombre de championnats du monde de boxe dans huit catégories de poids différentes, un exploit unique dans l'histoire de ce sport."),
        Question(8365, "Combien de championnats Manny Pacquiao a-t-il remportés?", listOf("8", "9", "10", "11"), 0, "Sport", Difficulty.HARD, explanation = "Manny Pacquiao est le seul boxeur de l'histoire à avoir remporté des titres mondiaux dans huit catégories de poids différentes, de la mouche aux super-welters."),
        Question(8366, "Quel est le record du plus grand nombre de victoires par KO?", listOf("42", "50", "58", "60"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus grand nombre de victoires par KO en boxe professionnelle est détenu par le Cubain Omar Narvaez, avec 58 KOs. Ce total inclut des combats dans les années 1990 et 2000."),
        Question(8367, "Qui a le plus de victoires par KO?", listOf("Joe Louis", "Muhammad Ali", "Lennox Lewis", "George Foreman"), 0, "Sport", Difficulty.HARD, explanation = "Joe Louis détient le record du plus grand nombre de victoires par KO dans l'histoire de la boxe poids lourds, avec 52 KO en 69 combats professionnels."),
        Question(8368, "Combien de KO Joe Louis a-t-il enregistrés?", listOf("42", "50", "58", "60"), 2, "Sport", Difficulty.HARD, explanation = "Joe Louis a remporté 58 de ses 69 victoires par KO, un record dans la catégorie des poids lourds, ce qui lui a valu le surnom de \"Bomber de Detroit\"."),
        Question(8369, "Quel est le record du plus long combat?", listOf("75", "100", "110", "120"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus long combat de boxe est de 110 rounds, disputé en 1893 entre Andy Bowen et Jack Burke, durant 7 heures et 19 minutes sans vainqueur déclaré."),
        Question(8370, "Quel match est connu comme le \"Fight of the Century\"?", listOf("Ali vs Frazier I", "Ali vs Foreman", "Ali vs Cleveland Williams", "Ali vs Terrell"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le combat entre Muhammad Ali et Joe Frazier en 1971 au Madison Square Garden est surnommé le \"Fight of the Century\" car il opposait deux champions invaincus pour le titre mondial des poids lourds, attirant une audience télévisée record."),
        Question(8371, "Quel est le record du plus grand nombre de défenses consécutives?", listOf("10", "15", "18", "20"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 18 défenses consécutives est détenu par le boxeur Floyd Mayweather Jr., qui a remporté tous ses combats professionnels entre 1996 et 2015 sans défaite."),
        Question(8372, "Qui a défendu le plus son titre consécutivement?", listOf("Joe Louis", "Muhammad Ali", "Lennox Lewis", "Evander Holyfield"), 0, "Sport", Difficulty.HARD, explanation = "Joe Louis a défendu son titre de champion du monde des poids lourds 25 fois consécutives entre 1937 et 1949, un record inégalé dans l'histoire de la boxe."),
        Question(8373, "Combien de défenses consécutives Joe Louis a-t-il effectuées?", listOf("10", "15", "18", "20"), 2, "Sport", Difficulty.HARD, explanation = "Joe Louis, surnommé le \"Bombardier de Détroit\", a défendu son titre de champion du monde des poids lourds 25 fois, mais le record de 18 défenses consécutives fait référence à une série spécifique entre 1937 et 1949, avant sa retraite temporaire."),
        Question(8374, "Quel est le record du plus grand nombre de victoires en carrière?", listOf("58", "68", "70", "78"), 3, "Sport", Difficulty.HARD, explanation = "Ce record de 78 victoires en carrière est détenu par le pilote de Formule 1 Lewis Hamilton, surpassant l'ancien record de Michael Schumacher (91 victoires)."),
        Question(8375, "Qui a le plus de victoires en carrière?", listOf("Muhammad Ali", "Archie Moore", "Joe Louis", "Jack Johnson"), 1, "Sport", Difficulty.HARD, explanation = "Archie Moore détient le record du plus grand nombre de victoires en carrière chez les boxeurs professionnels, avec 186 succès entre 1935 et 1963."),
        Question(8376, "Combien de victoires Archie Moore a-t-il enregistrées?", listOf("185", "195", "205", "215"), 2, "Sport", Difficulty.HARD, explanation = "Archie Moore détient le record du plus grand nombre de victoires par KO chez les boxeurs professionnels, avec 145 KO, et un total de 205 victoires en carrière."),
        Question(8377, "Quel est le record du plus grand nombre de défaites?", listOf("15", "20", "25", "30"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus grand nombre de défaites en championnat professionnel est détenu par le club de football anglais Derby County, avec 25 revers lors de la saison 2007-2008 de Premier League."),
        Question(8378, "Qui a le plus de défaites dans les records?", listOf("John Kaplan", "Joe Erskine", "Andy Baker", "Bill Hartman"), 0, "Sport", Difficulty.HARD, explanation = "John Kaplan détient le record du plus grand nombre de défaites en boxe professionnelle, avec 101 revers sur 135 combats entre 1946 et 1961."),
        Question(8379, "Quel est le record du plus grand poids pour un champion?", listOf("230 lb", "240 lb", "250 lb", "265 lb"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus grand poids pour un champion de boxe poids lourd est détenu par le Britannique Tyson Fury, qui pesait environ 250 livres (113 kg) lors de son combat contre Deontay Wilder en 2020."),
        Question(8380, "Quel combattant a pesé le plus?", listOf("Mohammad Ali", "George Foreman", "Tyson Fury", "Lennox Lewis"), 2, "Sport", Difficulty.HARD, explanation = "Tyson Fury est le plus lourd des combattants cités, son poids de combat atteignant régulièrement plus de 120 kg, ce qui le place au-dessus de la catégorie des poids lourds."),
        Question(8381, "Quel est le plus jeune champion du monde?", listOf("Mike Tyson", "Floyd Mayweather", "Manny Pacquiao", "Oscar De La Hoya"), 0, "Sport", Difficulty.MEDIUM, explanation = "Mike Tyson est devenu champion du monde poids lourds à 20 ans en 1986, ce qui reste le record de précocité pour un champion du monde de boxe."),
        Question(8382, "Quel âge avait Mike Tyson quand il est devenu champion?", listOf("18", "19", "20", "21"), 1, "Sport", Difficulty.MEDIUM, explanation = "Mike Tyson a battu Trevor Berbick le 22 novembre 1986 pour devenir le plus jeune champion du monde poids lourds de l'histoire, à 20 ans et 4 mois."),
        Question(8383, "Quel est le plus vieux champion du monde?", listOf("George Foreman", "Joe Louis", "Evander Holyfield", "Larry Holmes"), 0, "Sport", Difficulty.HARD, explanation = "George Foreman est devenu champion du monde des poids lourds à 45 ans en 1994, battant Michael Moorer, ce qui fait de lui le plus vieux champion du monde de boxe."),
        Question(8384, "Quel âge avait George Foreman quand il a retrouvé son titre?", listOf("45", "46", "48", "50"), 0, "Sport", Difficulty.HARD, explanation = "George Foreman avait 45 ans lorsqu'il a reconquis le titre de champion du monde poids lourds en battant Michael Moorer en 1994, devenant ainsi le plus vieux boxeur à remporter ce titre."),
        Question(8385, "Quel est le record du plus grand nombre de victoires par UD?", listOf("20", "25", "30", "35"), 2, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par le boxeur Ricardo López, qui a remporté 30 de ses 51 combats par décision unanime, sans jamais perdre un seul round sur les cartes des juges."),
        Question(8386, "Quel est le record du plus grand nombre d'années sans défaite?", listOf("10", "15", "20", "25"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 20 ans sans défaite est détenu par le club de football écossais Celtic Glasgow, qui n'a pas perdu un match à domicile en championnat entre 1901 et 1921."),
        Question(8387, "Qui a eu la plus longue série sans défaite?", listOf("Joe Calzaghe", "Joe Louis", "Muhammad Ali", "Rocky Marciano"), 0, "Sport", Difficulty.HARD, explanation = "Joe Calzaghe, boxeur gallois invaincu, a pris sa retraite avec 46 victoires consécutives, un record dans l'histoire de la boxe professionnelle pour un champion du monde."),
        Question(8388, "Quel est le record du plus grand nombre de matchs en une année?", listOf("15", "18", "20", "25"), 2, "Sport", Difficulty.HARD, explanation = "Le record du plus grand nombre de matchs en une année est détenu par le joueur de tennis Rafael Nadal, qui a disputé 20 finales en 2006."),
        Question(8389, "Qui a combattu le plus en une année?", listOf("Joe Louis", "Muhammad Ali", "Sugar Ray Robinson", "Jack Dempsey"), 2, "Sport", Difficulty.HARD, explanation = "Sugar Ray Robinson détient le record du plus grand nombre de combats professionnels en une seule année, avec 22 combats en 1951, dont 21 victoires et un match nul."),
        Question(8390, "Quel est le record du plus grand nombre de titres par divisions?", listOf("6", "7", "8", "9"), 2, "Sport", Difficulty.HARD, explanation = "Le record de huit titres par divisions est détenu par le boxeur américain Henry Armstrong, qui a été champion du monde dans trois catégories de poids différentes dans les années 1930."),
        Question(8391, "Qui a remporté le plus de titres dans différentes divisions?", listOf("Oscar De La Hoya", "Manny Pacquiao", "Muhammad Ali", "Henry Armstrong"), 1, "Sport", Difficulty.HARD, explanation = "Manny Pacquiao est le seul boxeur de l'histoire à avoir remporté des titres mondiaux dans huit catégories de poids différentes, des poids mouches aux super-welters."),
        Question(8392, "Combien de titres dans différentes divisions Manny Pacquiao a-t-il remportés?", listOf("6", "7", "8", "9"), 2, "Sport", Difficulty.HARD, explanation = "Manny Pacquiao est le seul boxeur de l'histoire à avoir remporté des titres mondiaux dans huit divisions de poids différentes, de la catégorie des poids mouche à celle des super-welters."),
        Question(8393, "Quel est le record du plus gros payday?", listOf("750 millions", "900 millions", "1 milliard", "1,2 milliard"), 3, "Sport", Difficulty.HARD, explanation = "Le plus gros gain de l'histoire du sport a été remporté par le boxeur Floyd Mayweather pour son combat contre Conor McGregor en 2017, incluant les recettes du pay-per-view."),
        Question(8394, "Quel combat a généré le plus d'argent?", listOf("Mayweather vs Pacquiao", "Mayweather vs McGregor", "Ali vs Foreman", "Hearns vs Hagler"), 1, "Sport", Difficulty.HARD, explanation = "Le combat de boxe entre Floyd Mayweather et Conor McGregor en 2017 a battu des records de revenus, générant environ 600 millions de dollars grâce aux ventes de billets et au pay-per-view."),
        Question(8395, "Quel est le record du plus grand nombre de victoires en défense?", listOf("30", "32", "35", "40"), 1, "Sport", Difficulty.HARD, explanation = "Ce record de 32 victoires consécutives en défense est détenu par le lutteur américain Dan Gable, réalisé entre 1968 et 1970 aux Jeux olympiques et aux championnats du monde."),
        Question(8396, "Quel est le record du plus court KO?", listOf("3s", "5s", "10s", "15s"), 1, "Sport", Difficulty.HARD, explanation = "Le KO le plus rapide de l'histoire de la boxe a été réalisé par Curtis Cokes en 5 secondes, bien que ce record soit parfois contesté. Le record officiel reconnu par le Guinness World Records est de 7 secondes, établi par Mike Collins en 1947."),
        Question(8397, "Quel est le record du nombre de combats disputés en carrière?", listOf("300", "350", "400", "450"), 2, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par le boxeur mexicain Julio César Chávez, qui a combattu 115 fois en carrière. Le nombre de 400 combats est une exagération, car aucun boxeur professionnel n'a atteint ce total, le record réel étant de 115 combats pour Chávez."),
        Question(8398, "Qui a disputé le plus de combats?", listOf("Archie Moore", "Jack Dempsey", "Muhammad Ali", "Joe Louis"), 0, "Sport", Difficulty.HARD, explanation = "Archie Moore détient le record du plus grand nombre de combats professionnels en boxe, avec 234 combats officiellement reconnus, s'étalant de 1935 à 1963."),
        Question(8399, "Quel est le record du plus grand nombre de victoires par Décision?", listOf("30", "32", "35", "38"), 2, "Sport", Difficulty.HARD, explanation = "Le boxeur Julio César Chávez détient ce record avec 35 victoires par décision, principalement en raison de son style technique et de sa longévité exceptionnelle dans les rings de boxe professionnelle."),

        // Jeux Olympiques (401-450)
        Question(8400, "En quelle année les premiers Jeux Olympiques modernes ont-ils eu lieu?", listOf("1892", "1896", "1900", "1904"), 1, "Sport", Difficulty.EASY, explanation = "Organisés par Pierre de Coubertin, les premiers Jeux Olympiques modernes se sont tenus à Athènes en 1896, marquant le renouveau de la tradition antique."),
        Question(8401, "Quel pays a accueilli les premiers Jeux Olympiques modernes?", listOf("France", "Royaume-Uni", "Grèce", "États-Unis"), 2, "Sport", Difficulty.MEDIUM, explanation = "Les premiers Jeux Olympiques modernes ont eu lieu à Athènes en 1896, organisés par Pierre de Coubertin, en hommage aux Jeux antiques nés en Grèce."),
        Question(8402, "Combien de fois les Jeux Olympiques ont-ils eu lieu?", listOf("28", "29", "30", "32"), 1, "Sport", Difficulty.HARD, explanation = "Les Jeux Olympiques modernes ont été organisés 29 fois entre 1896 et 2024, incluant les éditions annulées en 1916, 1940 et 1944 en raison des guerres mondiales."),
        Question(8403, "Quel athlète a remporté le plus de médailles olympiques?", listOf("Carl Lewis", "Paavo Nurmi", "Michael Phelps", "Larisa Latynina"), 2, "Sport", Difficulty.MEDIUM, explanation = "Michael Phelps détient le record du plus grand nombre de médailles olympiques avec 28, dont 23 en or, obtenues entre 2004 et 2016 en natation."),
        Question(8404, "Combien de médailles Michael Phelps a-t-il remportées?", listOf("20", "22", "23", "28"), 2, "Sport", Difficulty.EASY, explanation = "Michael Phelps détient le record du plus grand nombre de médailles olympiques, avec 23 titres obtenus entre 2004 et 2016, dont 18 en or."),
        Question(8405, "Quel est le record du plus grand nombre de médailles d'or?", listOf("20", "22", "23", "28"), 3, "Sport", Difficulty.HARD, explanation = "Michael Phelps détient ce record avec 28 médailles olympiques, dont 23 en or, obtenues entre 2004 et 2016."),
        Question(8406, "Qui détient le record du plus grand nombre de médailles d'or?", listOf("Michael Phelps", "Carl Lewis", "Paavo Nurmi", "Usain Bolt"), 0, "Sport", Difficulty.HARD, explanation = "Michael Phelps détient le record avec 23 médailles d'or olympiques, obtenues entre 2004 et 2016, principalement en natation."),
        Question(8407, "Combien de médailles d'or Michael Phelps a-t-il remportées?", listOf("20", "22", "23", "28"), 2, "Sport", Difficulty.EASY, explanation = "Michael Phelps détient le record du plus grand nombre de médailles d'or olympiques, avec 23 titres remportés entre 2004 et 2016, principalement en natation."),
        Question(8408, "Quel est le record du plus jeune médaillé d'or olympique?", listOf("10", "11", "12", "13"), 2, "Sport", Difficulty.HARD, explanation = "Le record est détenu par le plongeur chinois Fu Mingxia, qui a remporté l'or aux Jeux de Barcelone en 1992 à l'âge de 13 ans, mais la catégorie d'âge officielle est de 12 ans pour certains sports comme la gymnastique."),
        Question(8409, "Qui est le plus jeune médaillé d'or olympique?", listOf("Dimitrios Loundras", "Dimitris Loundras", "Kyoko Iwasaki", "Marjorie Gestring"), 3, "Sport", Difficulty.HARD, explanation = "Marjorie Gestring a remporté l'or en plongeon aux Jeux de Berlin en 1936 à l'âge de 13 ans, ce qui en fait la plus jeune médaillée d'or olympique de l'histoire."),
        Question(8410, "Quel est le record du plus vieux médaillé d'or olympique?", listOf("70", "72", "74", "80"), 2, "Sport", Difficulty.HARD, explanation = "Le tireur suédois Oscar Swahn a remporté sa dernière médaille d'or olympique en 1912 à l'âge de 64 ans, mais le record est détenu par le tireur suédois Oscar Swahn (non, c'est 74 ans) : en réalité, le record du plus vieux médaillé d'or olympique est de 74 ans, détenu par le cavalier suédois Carl Magnus Swahn (ou plutôt par le tireur Oscar Swahn à 64 ans, mais le record à 74 ans est celui du cav..."),
        Question(8411, "Qui est le plus vieux médaillé d'or olympique?", listOf("Oscar Swahn", "Dimitrios Loundras", "Sushi Marjorie Gestring", "Kyoko Iwasaki"), 0, "Sport", Difficulty.HARD, explanation = "Le tireur sportif suédois Oscar Swahn a remporté sa dernière médaille d'or olympique à 64 ans lors des Jeux de 1912 à Stockholm, ce qui fait de lui le médaillé d'or le plus âgé de l'histoire des Jeux olympiques modernes."),
        Question(8412, "Combien de fois les Jeux Olympiques d'été ont-ils été annulés?", listOf("1", "2", "3", "4"), 2, "Sport", Difficulty.HARD, explanation = "Les Jeux Olympiques d'été ont été annulés trois fois en raison des guerres mondiales : en 1916 (Berlin), 1940 (Tokyo/Helsinki) et 1944 (Londres)."),
        Question(8413, "En quelle année les Jeux Olympiques ont-ils été annulés?", listOf("1940, 1944", "1916, 1940, 1944", "1920, 1940, 1944", "1940, 1944, 1948"), 1, "Sport", Difficulty.HARD, explanation = "Les Jeux Olympiques ont été annulés en 1916 à cause de la Première Guerre mondiale, puis en 1940 et 1944 en raison de la Seconde Guerre mondiale."),
        Question(8414, "Quel athlète a remporté le plus de médailles d'or consécutives?", listOf("Usain Bolt", "Carl Lewis", "Paavo Nurmi", "Ray Ewry"), 3, "Sport", Difficulty.HARD, explanation = "Ray Ewry, spécialiste des sauts sans élan, a remporté 8 médailles d'or aux Jeux olympiques de 1900 à 1908, un record de titres consécutifs dans l'histoire olympique."),
        Question(8415, "Combien de médailles d'or Ray Ewry a-t-il remportées?", listOf("6", "8", "10", "12"), 2, "Sport", Difficulty.HARD, explanation = "Ray Ewry, atteint de poliomyélite dans son enfance, a dominé les sauts sans élan aux Jeux olympiques de 1900 à 1908, remportant 10 médailles d'or."),
        Question(8416, "Quel est le record du nombre de participations olympiques?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.HARD, explanation = "Plusieurs athlètes ont participé à six Jeux Olympiques, comme le cavalier canadien Ian Millar ou la judokate française Teddy Riner, ce qui constitue le record actuel."),
        Question(8417, "Qui a participé le plus aux Jeux Olympiques?", listOf("Ian Thorpe", "Vitaly Scherbo", "Ghislain Toro", "Carl Lewis"), 2, "Sport", Difficulty.HARD, explanation = "Le cavalier chilien Ghislain Toro détient le record du plus grand nombre de participations aux Jeux Olympiques, avec 13 éditions entre 1972 et 2020."),
        Question(8418, "Combien de fois Ian Thorpe a-t-il participé?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.HARD, explanation = "Ian Thorpe a participé à quatre éditions des Jeux Olympiques : Sydney 2000, Athènes 2004, Pékin 2008 et Londres 2012, totalisant cinq médailles d'or."),
        Question(8419, "Quel pays a accueilli les plus de Jeux Olympiques d'été?", listOf("France", "États-Unis", "Royaume-Uni", "Australie"), 1, "Sport", Difficulty.HARD, explanation = "Les États-Unis ont accueilli les Jeux Olympiques d'été à quatre reprises : Saint-Louis en 1904, Los Angeles en 1932 et 1984, et Atlanta en 1996, ce qui en fait le pays hôte le plus fréquent."),
        Question(8420, "Quel est le record du nombre de médailles en une journée olympique?", listOf("5", "6", "7", "8"), 2, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par le nageur américain Michael Phelps, qui a remporté 7 médailles (dont 5 en or) lors d'une seule journée des Jeux olympiques de 2008 à Pékin."),
        Question(8421, "Quel est le record du nombre de médailles remportées par un pays?", listOf("200", "250", "300", "350"), 2, "Sport", Difficulty.HARD, explanation = "Les États-Unis ont accumulé plus de 3 000 médailles olympiques au total, mais le record de 300 médailles lors d’une seule édition est détenu par la Chine aux Jeux paralympiques de 2022."),
        Question(8422, "Quel pays a remporté le plus de médailles olympiques?", listOf("Royaume-Uni", "Russie", "États-Unis", "Allemagne"), 2, "Sport", Difficulty.HARD, explanation = "Les États-Unis dominent le classement historique des médailles olympiques avec plus de 2 600 médailles, grâce à leur forte participation et leurs performances dans des sports comme l'athlétisme et la natation."),
        Question(8423, "Quel est le record du nombre de médailles d'or remportées par un pays?", listOf("100", "150", "200", "250"), 2, "Sport", Difficulty.HARD, explanation = "Les États-Unis ont remporté 200 médailles d'or aux Jeux olympiques d'hiver de 2022 à Pékin, établissant un record pour le plus grand nombre de médailles d'or obtenues par un pays lors d'une seule édition des Jeux."),
        Question(8424, "Quel pays a remporté le plus de médailles d'or?", listOf("Russie", "Allemagne", "États-Unis", "Royaume-Uni"), 2, "Sport", Difficulty.HARD, explanation = "Les États-Unis dominent le classement historique des médailles d'or aux Jeux Olympiques, avec plus de 1 000 titres obtenus depuis 1896, loin devant les autres nations."),
        Question(8425, "Combien de fois Usain Bolt a-t-il remporté l'or au 100m?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.MEDIUM, explanation = "Usain Bolt a remporté l'or olympique du 100 mètres aux Jeux de Pékin en 2008, de Londres en 2012 et de Rio en 2016, soit trois titres consécutifs."),
        Question(8426, "Quel est le record olympique du 100m hommes?", listOf("9.58s", "9.63s", "9.69s", "9.95s"), 3, "Sport", Difficulty.HARD, explanation = "Ce record a été établi par le Jamaïcain Usain Bolt lors des Jeux olympiques de Pékin en 2008, où il a couru le 100 mètres en 9,69 secondes, mais le record officiel est de 9,63 secondes, réalisé aux Jeux de Londres en 2012."),
        Question(8427, "Qui détient le record olympique du 100m hommes?", listOf("Usain Bolt", "Yohan Blake", "Tyson Gay", "Donovan Bailey"), 0, "Sport", Difficulty.MEDIUM, explanation = "Usain Bolt a établi le record olympique du 100 mètres hommes en 9,63 secondes lors des Jeux de Londres en 2012, performance qu'il n'a pas améliorée par la suite."),
        Question(8428, "Quel est le record olympique du marathon hommes?", listOf("2:03:23", "2:06:32", "2:08:16", "2:10:00"), 1, "Sport", Difficulty.HARD, explanation = "Le record olympique du marathon masculin a été établi par le Kényan Samuel Wanjiru aux Jeux de Pékin en 2008, avec un temps de 2:06:32. Cette performance reste inégalée car les parcours olympiques varient et ne sont pas toujours aussi rapides."),
        Question(8429, "Qui détient le record olympique du marathon?", listOf("Eliud Kipchoge", "Samuel Wanjiru", "Yuri Kakorin", "Gezahegne Abera"), 0, "Sport", Difficulty.HARD, explanation = "Eliud Kipchoge a établi le record olympique du marathon en 2h08m38s lors des Jeux de Tokyo en 2021, où il a remporté la médaille d'or."),
        Question(8430, "Quel est le record olympique du saut en longueur?", listOf("8.72m", "8.90m", "8.95m", "9.00m"), 2, "Sport", Difficulty.HARD, explanation = "Le record olympique du saut en longueur est de 8,95 mètres, établi par l'Américain Mike Powell aux Jeux de Barcelone en 1992. Ce record n'a pas été battu depuis."),
        Question(8431, "Qui détient le record olympique du saut en longueur?", listOf("Bob Beamon", "Mike Powell", "Carl Lewis", "Ivan Pedroso"), 0, "Sport", Difficulty.HARD, explanation = "Bob Beamon a établi le record olympique du saut en longueur aux Jeux de Mexico en 1968, avec un bond de 8,90 mètres, un record du monde qui a tenu 23 ans."),
        Question(8432, "Quel est le record olympique du saut en hauteur?", listOf("2.39m", "2.40m", "2.44m", "2.48m"), 0, "Sport", Difficulty.HARD, explanation = "Le record olympique du saut en hauteur est de 2,39 mètres, établi par Charles Austin aux Jeux d'Atlanta en 1996. Ce record masculin tient toujours depuis cette édition."),
        Question(8433, "Qui détient le record olympique du saut en hauteur?", listOf("Javier Sotomayor", "Charles Austin", "Sergei Kliuev", "Hamish Kerr"), 0, "Sport", Difficulty.HARD, explanation = "Le record olympique du saut en hauteur est détenu par le Cubain Javier Sotomayor, qui a sauté 2,45 mètres aux Jeux de Barcelone en 1992."),
        Question(8434, "Quel est le record olympique du triple saut?", listOf("17.39m", "17.69m", "18.09m", "18.29m"), 2, "Sport", Difficulty.HARD, explanation = "Le record olympique du triple saut masculin est détenu par Kenny Harrison avec 18,09 m, établi aux Jeux d'Atlanta en 1996."),
        Question(8435, "Qui détient le record olympique du triple saut?", listOf("Jonathan Edwards", "Willie Banks", "Kenny Harrison", "Aleksandr Saneyev"), 0, "Sport", Difficulty.HARD, explanation = "Jonathan Edwards a établi le record olympique du triple saut avec 18,09 mètres aux Jeux de Sydney en 2000, performance qui reste inégalée aux Jeux."),
        Question(8436, "Quel est le record olympique du 100m nage libre femmes?", listOf("52.70s", "53.36s", "53.42s", "54.00s"), 2, "Sport", Difficulty.HARD, explanation = "Le record olympique du 100 mètres nage libre femmes est de 53,42 secondes, établi par la nageuse australienne Mollie O'Callaghan lors des Jeux de Paris en 2024."),
        Question(8437, "Qui détient le record olympique du 100m nage libre femmes?", listOf("Penny Oleksiak", "Bronte Campbell", "Margaret Hoelzer", "Dana Vollmer"), 0, "Sport", Difficulty.HARD, explanation = "Penny Oleksiak a établi ce record en 2016 aux Jeux de Rio, avec un temps de 52,70 secondes, devenant ainsi la plus jeune médaillée olympique canadienne."),
        Question(8438, "Quel est le record olympique du 100m nage libre hommes?", listOf("47.52s", "47.68s", "47.74s", "48.00s"), 1, "Sport", Difficulty.HARD, explanation = "Le record olympique du 100m nage libre hommes est détenu par Kyle Chalmers, qui a réalisé 47,68 secondes lors des Jeux de Rio en 2016."),
        Question(8439, "Qui détient le record olympique du 100m nage libre hommes?", listOf("Michael Phelps", "Caeleb Dressel", "Nathan Adrian", "Florent Manaudou"), 1, "Sport", Difficulty.HARD, explanation = "Caeleb Dressel a établi le record olympique du 100 mètres nage libre hommes avec un temps de 47,02 secondes lors des Jeux de Tokyo 2020."),
        Question(8440, "Quel est le record olympique du 200m nage libre?", listOf("1:42.96", "1:43.00", "1:44.00", "1:45.00"), 0, "Sport", Difficulty.HARD, explanation = "Le record olympique du 200 mètres nage libre masculin est détenu par Michael Phelps, qui a réalisé un temps de 1 minute 42 secondes et 96 centièmes lors des Jeux de Pékin en 2008."),
        Question(8441, "Qui détient le record olympique du 200m nage libre?", listOf("Michael Phelps", "Yannick Agnèl", "Paul Biedermann", "Grant Hackett"), 0, "Sport", Difficulty.HARD, explanation = "Michael Phelps a établi ce record aux Jeux olympiques de Pékin en 2008, avec un temps de 1 minute 42 secondes et 96 centièmes."),
        Question(8442, "Quel est le record olympique du 400m nage libre?", listOf("3:40.07", "3:42.58", "3:43.00", "3:45.00"), 0, "Sport", Difficulty.HARD, explanation = "Le record olympique du 400 mètres nage libre est détenu par le nageur allemand Paul Biedermann, établi aux Jeux de Pékin en 2008. Ce temps de 3:40.07 a été réalisé en finale, surpassant l'ancien record de Ian Thorpe."),
        Question(8443, "Qui détient le record olympique du 400m nage libre?", listOf("Yang Sun", "Ian Thorpe", "Kieren Perkins", "Tom Dolan"), 0, "Sport", Difficulty.HARD, explanation = "Le nageur chinois Yang Sun a établi le record olympique du 400 m nage libre en 3 minutes 40 secondes 14 centièmes lors des Jeux de Londres en 2012."),
        Question(8444, "Quel est le record olympique du 1500m nage libre femmes?", listOf("15:20.48", "15:28.36", "15:35.00", "16:00.00"), 0, "Sport", Difficulty.HARD, explanation = "Le record olympique du 1500 mètres nage libre femmes a été établi par Katie Ledecky aux Jeux de Tokyo 2020, avec un temps de 15 minutes 20 secondes et 48 centièmes."),
        Question(8445, "Qui détient le record olympique du 1500m nage libre femmes?", listOf("Katie Ledecky", "Hannah Moore", "Heather Fredrick", "Jessica Hardy"), 0, "Sport", Difficulty.HARD, explanation = "Katie Ledecky a établi ce record olympique aux Jeux de Rio 2016 en 15 min 35 sec 35, un temps qui reste la meilleure performance mondiale de l'histoire sur la distance."),
        Question(8446, "Quel est le record olympique du 1500m nage libre hommes?", listOf("14:30.40", "14:31.00", "14:33.00", "14:35.00"), 1, "Sport", Difficulty.HARD, explanation = "Ce record a été établi par l'Américain Robert Finke aux Jeux de Tokyo 2020, battant l'ancien record de 14:34.56 détenu par Sun Yang depuis 2012."),
        Question(8447, "Qui détient le record olympique du 1500m nage libre hommes?", listOf("Gregorio Paltrinieri", "Kieren Perkins", "Grant Hackett", "Vladimir Salnikov"), 0, "Sport", Difficulty.HARD, explanation = "Gregorio Paltrinieri a établi le record olympique du 1500 mètres nage libre hommes en 14 minutes 34 secondes 57 aux Jeux de Rio en 2016, où il a remporté la médaille d'or."),
        Question(8448, "Quel est le record olympique du 100m brasse hommes?", listOf("56.88s", "57.00s", "57.13s", "57.30s"), 0, "Sport", Difficulty.HARD, explanation = "Ce temps a été réalisé par le Britannique Adam Peaty aux Jeux de Rio en 2016, établissant un record olympique qui tient toujours."),
        Question(8449, "Qui détient le record olympique du 100m brasse hommes?", listOf("Adam Peaty", "Kosuke Kitajima", "Brendan Hansen", "Ed Moses"), 0, "Sport", Difficulty.HARD, explanation = "Adam Peaty a établi le record olympique du 100 m brasse avec un temps de 57,13 secondes aux Jeux de Rio 2016, performance qu'il a ensuite améliorée aux Mondiaux."),

        // Handball (451-500)
        Question(8450, "Quel est le nombre de joueurs dans une équipe de handball?", listOf("7", "9", "11", "13"), 0, "Sport", Difficulty.EASY, explanation = "Au handball, chaque équipe aligne 7 joueurs sur le terrain, dont un gardien de but. Cette règle est définie par la Fédération Internationale de Handball."),
        Question(8451, "Combien de fois la France a-t-elle remporté le Championnat du Monde de handball?", listOf("4", "5", "6", "7"), 2, "Sport", Difficulty.MEDIUM, explanation = "La France a remporté le Championnat du Monde de handball à six reprises, en 1995, 2001, 2009, 2011, 2015 et 2017, ce qui en fait le pays le plus titré de la compétition masculine."),
        Question(8452, "Quel est le record du nombre de buts marqués en un match de handball?", listOf("55", "60", "65", "70"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 65 buts en un match de handball a été établi lors d'une rencontre entre l'Islande et la Norvège en 2019, avec un score final de 36-29. Ce total exceptionnel s'explique par un rythme offensif élevé et peu d'arrêts défensifs."),
        Question(8453, "Qui a remporté la Coupe du Monde de handball féminin en 2021?", listOf("Espagne", "France", "Russie", "Norvège"), 0, "Sport", Difficulty.MEDIUM, explanation = "L'Espagne a remporté le Championnat du monde féminin de handball 2021 en battant la France en finale. C'était leur premier titre mondial dans cette discipline."),
        Question(8454, "Quel est le record du nombre de championnats européens remportés?", listOf("4", "5", "6", "7"), 1, "Sport", Difficulty.HARD, explanation = "Le Real Madrid détient le record avec 5 victoires en Coupe d'Europe des clubs champions (ancêtre de la Ligue des champions), remportées en 1956, 1957, 1958, 1959 et 1960."),
        Question(8455, "Quel pays a remporté le plus de championnats européens?", listOf("France", "Suède", "Allemagne", "Espagne"), 0, "Sport", Difficulty.HARD, explanation = "La France détient le record du nombre de victoires au Championnat d'Europe de football, avec deux titres en 1984 et 2000. Aucune autre nation n'a fait mieux dans cette compétition."),
        Question(8456, "Combien de championnats européens la France a-t-elle remportés?", listOf("4", "5", "6", "7"), 1, "Sport", Difficulty.HARD, explanation = "La France a remporté le Championnat d'Europe de football en 1984 et 2000, ainsi que trois autres titres européens dans d'autres sports collectifs, portant le total à cinq."),
        Question(8457, "Quel est le record du nombre de victoires consécutives en handball?", listOf("8", "10", "12", "15"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 12 victoires consécutives en handball est détenu par l'équipe de France masculine, réalisé entre 2015 et 2017, incluant leur titre olympique à Rio en 2016."),
        Question(8458, "Qui a remporté la Coupe du Monde de handball hommes en 2023?", listOf("France", "Espagne", "Suède", "Norwège"), 0, "Sport", Difficulty.MEDIUM, explanation = "L'équipe de France masculine de handball a remporté le championnat du monde 2023 en battant le Danemark en finale, décrochant ainsi son sixième titre mondial."),
        Question(8459, "Combien de fois la Suède a-t-elle remporté la Coupe du Monde?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.MEDIUM, explanation = "La Suède a remporté la Coupe du Monde de football à une reprise, en 1958, lorsqu'elle était pays hôte. La bonne réponse est donc 1, et non 3."),
        Question(8460, "Quel est le record du nombre de buts marqués par un joueur en carrière?", listOf("1000", "1500", "2000", "2500"), 2, "Sport", Difficulty.HARD, explanation = "Le record du nombre de buts marqués en carrière est détenu par le Brésilien Pelé, avec 767 buts officiels en matchs, bien que certaines sources incluent des matchs amicaux pour atteindre environ 2000 buts. Ce chiffre est souvent cité dans le débat sur les meilleurs buteurs de l'histoire."),
        Question(8461, "Qui a marqué le plus de buts en carrière?", listOf("Nikola Karabatic", "Igor Anic", "Jackson Richardson", "Holger Glandrup"), 1, "Sport", Difficulty.HARD, explanation = "Igor Anic est un joueur de handball français, considéré comme l’un des meilleurs buteurs de l’histoire de ce sport, avec plus de 4 000 buts marqués en compétitions officielles."),
        Question(8462, "Combien de buts Igor Anic a-t-il marqués?", listOf("500", "1000", "1500", "2000"), 2, "Sport", Difficulty.HARD, explanation = "Igor Anic, joueur de handball français, a marqué 1500 buts en sélection nationale, un record pour l'équipe de France. Il est connu pour sa carrière au Montpellier Handball et en équipe de France."),
        Question(8463, "Quel est le record du nombre de buts marqués par un joueur en un match?", listOf("15", "16", "17", "18"), 1, "Sport", Difficulty.HARD, explanation = "Ce record est détenu par le joueur de football Archie Thompson, qui a inscrit 16 buts pour l'Australie lors d'une victoire 31-0 contre les Samoa américaines en 2001."),
        Question(8464, "Quel est le record du nombre de buts marqués par une équipe en un match?", listOf("40", "45", "50", "55"), 2, "Sport", Difficulty.HARD, explanation = "Ce record a été établi en 1885 par Arbroath FC, qui a battu Bon Accord 36-0 en Coupe d'Écosse. Le score de 50-0 est souvent cité par erreur, mais le record officiel est de 36 buts."),
        Question(8465, "Quel est le record du nombre de buts marqués par une équipe en une saison?", listOf("500", "600", "700", "800"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 700 buts en une saison a été établi par le club écossais du Celtic Glasgow lors de la saison 1966-1967, toutes compétitions confondues."),
        Question(8466, "Quel est le record du nombre de victoires en Ligue des Champions?", listOf("3", "4", "5", "6"), 2, "Sport", Difficulty.HARD, explanation = "Le Real Madrid détient le record avec 15 victoires en Ligue des Champions, et non 5. Ce chiffre correspond plutôt au nombre de titres remportés par un club comme Barcelone ou Liverpool."),
        Question(8467, "Quel club a remporté le plus de Ligue des Champions?", listOf("FC Barcelona", "Paris Saint-Germain", "THW Kiel", "Montpellier"), 0, "Sport", Difficulty.HARD, explanation = "Le FC Barcelone détient le record de victoires en Ligue des Champions féminine avec 8 titres, dont le dernier en 2023. C'est le club le plus titré de l'histoire de la compétition."),
        Question(8468, "Combien de Ligue des Champions le FC Barcelona a-t-il remportées?", listOf("2", "3", "4", "5"), 2, "Sport", Difficulty.HARD, explanation = "Le FC Barcelone a remporté sa première Ligue des Champions en 1992, puis en 2006, 2009, 2011 et 2015, soit cinq titres au total. La réponse correcte est donc 5, et non 4."),
        Question(8469, "Quel est le record du nombre d'arrêts en un match de handball?", listOf("15", "16", "17", "18"), 1, "Sport", Difficulty.HARD, explanation = "Le record de 16 arrêts en un match de handball a été établi par le gardien français Thierry Omeyer lors de la finale des Jeux olympiques de 2008 contre l'Islande."),
        Question(8470, "Quel est le record du nombre d'arrêts en une saison?", listOf("200", "250", "300", "350"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 300 arrêts en une saison a été établi par le gardien de but de hockey sur glace Martin Brodeur lors de la saison 2006-2007 de la LNH."),
        Question(8471, "Quel gardien a effectué le plus d'arrêts en carrière?", listOf("Dominik Klein", "Thomas Haab", "Thierry Omeyer", "Silvio Heinevetter"), 2, "Sport", Difficulty.HARD, explanation = "Thierry Omeyer, considéré comme l'un des meilleurs gardiens de handball, détient le record du nombre d'arrêts en carrière grâce à sa longévité et ses performances exceptionnelles en club et en équipe de France."),
        Question(8472, "Combien d'arrêts Thierry Omeyer a-t-il effectués?", listOf("500", "1000", "1500", "2000"), 1, "Sport", Difficulty.HARD, explanation = "Thierry Omeyer, considéré comme l'un des meilleurs gardiens de handball, a atteint le cap des 1000 arrêts en compétition officielle, un record symbolique dans l'histoire du sport."),
        Question(8473, "Quel est le record du nombre de passes décisives?", listOf("200", "300", "400", "500"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 400 passes décisives est détenu par le joueur de football américain Tom Brady, établi tout au long de sa carrière en NFL, une performance inégalée dans ce sport."),
        Question(8474, "Qui a effectué le plus de passes décisives?", listOf("Nikola Karabatic", "Igor Anic", "Jackson Richardson", "Holger Glandrup"), 0, "Sport", Difficulty.HARD, explanation = "Nikola Karabatic détient le record du nombre de passes décisives en handball, notamment grâce à sa longévité et son rôle de chef d'orchestre au poste d'arrière gauche."),
        Question(8475, "Combien de passes décisives Nikola Karabatic a-t-il effectuées?", listOf("200", "300", "400", "500"), 2, "Sport", Difficulty.HARD, explanation = "Nikola Karabatic est devenu le premier joueur de l’histoire du championnat de France de handball à atteindre la barre des 400 passes décisives en février 2023."),
        Question(8476, "Quel est le record du nombre de buts en 7 matchs?", listOf("50", "60", "70", "80"), 1, "Sport", Difficulty.HARD, explanation = "Ce record a été établi lors de la Coupe du monde de rugby à XV en 2003, où l'Australie a marqué 60 points contre la Namibie. Il s'agit du plus grand nombre de points inscrits par une équipe en sept matchs dans l'histoire de la compétition."),
        Question(8477, "Quel est le record du plus grand nombre de victoires consécutives en coupe?", listOf("10", "12", "15", "18"), 2, "Sport", Difficulty.HARD, explanation = "Le Real Madrid détient ce record avec 15 victoires consécutives en Ligue des champions, une série établie entre 2015 et 2018 sous la direction de Zinedine Zidane."),
        Question(8478, "Quel est le record du plus grand nombre de victoires en Coupe de France?", listOf("2", "3", "4", "5"), 2, "Sport", Difficulty.HARD, explanation = "Le record est détenu par le Paris Saint-Germain avec 14 victoires, et non 4. Aucun club n'a remporté la Coupe de France exactement 4 fois."),
        Question(8479, "Quel club a remporté le plus de Coupe de France?", listOf("Dunkerque", "Montpellier", "Saint-Raphaël", "Toulouse"), 0, "Sport", Difficulty.HARD, explanation = "L'USL Dunkerque détient le record du plus grand nombre de victoires en Coupe de France de football, avec 7 titres remportés entre 1918 et 1931."),
        Question(8480, "Combien de Coupe de France Dunkerque a-t-il remportées?", listOf("2", "3", "4", "5"), 2, "Sport", Difficulty.HARD, explanation = "Dunkerque a remporté la Coupe de France à quatre reprises, en 1959, 1960, 1961 et 1962, réalisant un exploit rare dans l'histoire du football français."),
        Question(8481, "Quel est le record du nombre de buts marqués par une équipe sur une saison en championnat?", listOf("800", "850", "900", "950"), 1, "Sport", Difficulty.HARD, explanation = "Ce record a été établi par le Real Madrid lors de la saison 2011-2012, toutes compétitions confondues, mais en championnat d'Espagne, l'équipe a marqué 121 buts, et non 850. Le chiffre de 850 correspond au record de buts marqués par une équipe de hockey sur glace en une saison de LNH."),
        Question(8482, "Quel est le record du nombre de buts marqués par une équipe en demi-finale?", listOf("30", "35", "40", "45"), 2, "Sport", Difficulty.HARD, explanation = "Ce record a été établi par l'équipe de France de handball lors des Jeux Olympiques de 2008, où elle a marqué 40 buts contre la Croatie en demi-finale."),
        Question(8483, "Quel est le record du plus grand nombre de buts encaissés en un match?", listOf("30", "35", "40", "45"), 2, "Sport", Difficulty.HARD, explanation = "Ce record a été établi en 1885 lors d'un match entre l'Arbroath FC et le Bon Accord, où Arbroath a gagné 36-0, mais le score officiel le plus élevé est de 149-0, un match de 2002 à Madagascar où l'équipe perdante a délibérément marqué des buts contre son camp pour protester contre l'arbitrage."),
        Question(8484, "Quel est le record du plus grand nombre de buts encaissés en une saison?", listOf("400", "500", "600", "700"), 2, "Sport", Difficulty.HARD, explanation = "Le record de 600 buts encaissés en une saison a été établi par le club écossais d'Arbroath FC lors de la saison 1885-1886, une époque où les scores étaient souvent très élevés dans le football amateur."),
        Question(8485, "Quel est le record du nombre de victoires en compétition internationale?", listOf("50", "100", "150", "200"), 2, "Sport", Difficulty.HARD, explanation = "Ce record de 150 victoires en compétition internationale est détenu par le nageur Michael Phelps, qui totalise 28 médailles olympiques et 26 titres mondiaux."),
        Question(8486, "Quel équipe a le plus de victoires en compétition internationale?", listOf("France", "Suède", "Allemagne", "Espagne"), 0, "Sport", Difficulty.HARD, explanation = "L'équipe de France de football détient le record de victoires en Coupe du monde avec deux titres, en 1998 et 2018. Elle compte également deux victoires en Championnat d'Europe des nations, en 1984 et 2000."),
        Question(8487, "Quel est le record du nombre de médailles remportées en Coupes du Monde?", listOf("5", "6", "7", "8"), 1, "Sport", Difficulty.HARD, explanation = "Le record de six médailles en Coupes du Monde est détenu par le footballeur brésilien Pelé, qui a remporté trois Coupes du Monde (1958, 1962, 1970) et trois autres médailles lors d'autres compétitions internationales."),
        Question(8488, "Quel est le record du nombre de participations en Coupe du Monde?", listOf("15", "16", "17", "18"), 1, "Sport", Difficulty.HARD, explanation = "Lionel Messi détient ce record avec 26 matchs joués en Coupe du Monde, mais le record de participations en tant que joueur (nombre de tournois disputés) est de 5, partagé par plusieurs joueurs comme Antonio Carbajal et Lothar Matthäus."),
        Question(8489, "Quel est le record du nombre de buts marqués par une équipe en 3 matchs?", listOf("80", "90", "100", "110"), 2, "Sport", Difficulty.HARD, explanation = "Le record des 100 buts en trois matchs a été établi par l'équipe de football des îles Salomon en 2015, lors des éliminatoires de la Coupe du monde, contre des adversaires comme les Samoa américaines."),
